WordHunterWoW_QuestDataByFlavor = WordHunterWoW_QuestDataByFlavor or {}
WordHunterWoW_QuestDataByFlavor.classic = WordHunterWoW_QuestDataByFlavor.classic or {}
WordHunterWoW_QuestDataByFlavor.classic.deDE = WordHunterWoW_QuestDataByFlavor.classic.deDE or {}
local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[4864] = { title = "Wütende Wildekin", description = "Nachdem Ihr den Inhalt des Kastens inspiziert habt, befindet Ihr, dass Jaron die Werkzeuge und anderen Gegenstände darin sicher gebrauchen könnte. Von dem Amulett fehlt jedoch jede Spur.\n\nDie Wildekin scheinen die Landstriche nördlich und östlich von hier zu bewohnen, also beschließt Ihr, dass Euer nächster Schritt sein wird, die Kreaturen aufzustöbern und das Amulett von ihnen einzufordern.", objectives = "Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte.\n\nBringt Jaron Stoneshaper in der Lodge in Winterspring dessen Vorräte und das blaugefiederte Amulett.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4865] = { title = "Wilde Schlange", description = "Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich es nie für möglich gehalten haben. Die Rache kam nach Tausend Nadeln!\n\n<Hagar wischt sich den Schweiß von der Stirn.>\n\n$N, Ihr müsst Euch beeilen! Geht sofort los und sucht Motega Firemane auf. Ihr findet ihn im Weißgipfelposten nordwestlich des Freiwindpostens, entlang der Straße. Er wird wissen, was zu tun ist!", objectives = "Berichtet Motega Firemane von Euren Entdeckungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4866] = { title = "Muttermilch", description = "Das dürfte eines der stärksten Gifte der Welt sein, $R!\n\nIch habe bei meinen Ausflügen zur Spitze immer wieder gehört, wie die Leute von Blackrock davon sprachen, wie tödlich es sei. Sie nennen es 'Muttermilch', benannt nach Mutter Glimmernetz, der großen, grausamen Spinne in der Skitterwebhöhle.\n\nAlso, das müsst Ihr mir besorgen: eine frische Probe dieser Milch, die durch EURE Adern fließt. Mir einfach nur die Giftdrüse zu bringen, wäre nicht genug! Bringt sie dazu, Euch zu vergiften, und kommt dann zu mir zurück!\n\nDann... kann ich Euch melken!\n\n<Reibt sich voller Vorfreude die Hände.>", objectives = "Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4867] = { title = "Urok Schreckensbote", description = "Argh! Das Sprechen fällt schwer!\n\nNehmt diese Notiz! Holt mir mein Mojo.", objectives = "Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4881] = { title = "Auftragsmordplan", description = "Der Tauren Kanati Greycloud war so dreist, in Tausend Nadeln ein Jägerlager aufzuschlagen. Wir müssen ihn töten, damit dieses Jägerlager und alle, die ihm möglicherweise folgen, verschwinden. Wir werden uns dem kleinen Posten südwestlich des großen Aufzugs nähern.", objectives = "Warnt Kanati Greycloud am Weißgipfelposten, dass man vorhat, ihn zu töten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4882] = { title = "Geheimnisse bewachen", description = "Ihr seid Euch unsicher bezüglich der Bedeutung der Halskette, die vom Hals des gerade erschlagenen Wildekin stammt. Sie glüht hell, verblasst und wird wieder hell.\n\nTrull Failbane kann Euch vielleicht mehr darüber sagen, da er über sehr großes Wissen über die Wildekin verfügt. Vielleicht solltet Ihr ihn darüber befragen.", objectives = "Bringt Trull Failbane beim Blutgiftposten das blaugefiederte Amulett.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4883] = { title = "Geheimnisse bewahren", description = "Auch wenn ich viel über die Eulenbestien weiß, die Ihr in Winterspring erledigt habt, bin ich in der Magie, die sie wirken, nicht wirklich bewandert. Aber ich glaube, dass ich jemanden kenne, der die Kette untersuchen und Euch sagen könnte, was es ist.\n\nNara Wildmane in Thunder Bluff ist eine Expertin auf diesem Gebiet; trefft Euch mit ihr. Viel Glück, $N.", objectives = "Bringt Nara Wildmane das blaugefiederte Amulett.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4901] = { title = "Wächter des Altars", description = "Ganz oben auf dem Grat liegt das, was ich für einen Altar der Göttin Elune halte. Soweit ich das sagen kann, müssen wir in jeder Höhle fünf Fackeln anzünden. Dann können wir den eigentlichen Altar erreichen.\n\nIch habe einige der Zauberformeln übersetzt, die in den Stein der alten Ruinen von Kel'Theril geritzt sind. Meiner Meinung nach sind sie der Schlüssel, mit dem man den Altar freigeben kann. Ich brauche Eure Hilfe dabei, alle Fackeln anzuzünden, während ich den Zauber rezitiere.\n\nWenn wir Erfolg haben, könnt Ihr Erelas unseren Fund melden!", objectives = "Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Ambersky in Rut'theran von Eurem Fund.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4902] = { title = "Wildekin von Elune", description = "Das ist faszinierend!\n\nIch habe mich immer gefragt, was die Wahrheit ist... Nun, Ihr müsst dieses Wissen auf alle Fälle teilen! Geht sofort zum Erzdruiden Fandral Staghelm. Ihr werdet ihn in Darnassus im Zirkel des Cenarius antreffen. Erklärt ihm, was passiert ist, genau so wie Ihr es mir erzählt habt. Ich bin sicher, es wird ihn ebenso interessieren!\n\nDas sind wichtige Informationen, $N!", objectives = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4903] = { title = "Befehl des Kriegsherrn", description = "Auf Befehl von Kriegsherr Goretooth müssen die nachfolgenden Bewohner der Blackrockspitze eliminiert werden:\n\nDie aufgeblasene Bedrohung, Hochlord Omokk.\n\nDer grausame und erbarmungslose Troll Kriegsmeister Voone.\n\nOberanführer Wyrmthalak, Zuchtmeister der geringen Stadt.\n\nDes Weiteren müsst Ihr alle wichtigen Dokumente zurückbringen, die Ihr möglicherweise findet.\n\nSeid erfolgreich und macht Euch Ehre.\n\nVersagt und seid vergessen.", objectives = "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4904] = { title = "Endlich frei", description = "Arnak glaubt, dass wir heiraten werden… aber nachdem ich seinen Antrag abgelehnt hatte, kehrte er in der Nacht zurück und entführte mich. Mein Bruder wollte ihn aufhalten, aber Arnak war einfach zu stark. Er... er tötete meinen Bruder, dann brachte er mich hierher. Mein armer Bruder...\n\n$n, würdet Ihr mich wohl vom Düsterwolkengipfel hinab geleiten? Bitte... ich muss zu Thalia zurückkehren! Sie macht sich bestimmt große Sorgen um mich.", objectives = "Geleitet Lakota Windsong vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Amberhide.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4906] = { title = "Weitere Verderbnis", description = "Ein weiterer Satyrstützpunkt unter der Leitung des grausamen Xavaric bedroht den Teufelswald im Norden. Die elenden Verräter und Schwindler zehren von der Verderbnis der im Teufelswald heimischen Kreaturen.\n\nXavathras und seine Diener waren nur Teil eines größeren Plans - ein Mondbrunnen sollte verderbt werden und Xavaric sollte dann die Beute bekommen.\n\nDa Xavathras jetzt beseitigt ist, solltet Ihr diese Aufgabe beenden, $n. Geht nach Norden und besiegt Xavaric.", objectives = "Eridan Bluewind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4907] = { title = "Tinkee Kesseldampf", description = "Hallo, $N. Erinnert Ihr Euch an Tinkee Steamboil? Tja, sie erinnert sich jedenfalls an Euch! Sie schickte mir eine Nachricht, dass ich nach Euch Ausschau halten soll... sie braucht nämlich nochmals Eure Hilfe. Ich glaube, es hat was mit ihren Drachenstudien zu tun.\n\nIhr solltet mit ihr sprechen. Sie ist in der brennenden Steppe, beim Flammenkamm.", objectives = "Sprecht mit Tinkee Steamboil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4921] = { title = "In der Schlacht vermisst", description = "Wir wurden getrennt, als wir in einem kleinen Taurenlager gemeinsam kämpften - sie hat drei Borstennacken im Alleingang bezwungen. Aber dann waren sie plötzlich in der Überzahl. Ich lockte ein paar fort, dann sah ich, wie sie von Neuankömmlingen überwältigt wurde. Rasend vor Zorn stellte ich mich meinen Feinden, aber da es derer so viele waren, ging ich schon bald zu Boden.\n\nIch kam im Zelt eines Taurendruiden zu mir, der meine Wunden versorgte - er kam zufällig die Goldstraße entlang, als ich fiel.\n\nBitte, $C, sucht nach einem Lebenszeichen von meiner Frau.", objectives = "Sucht Mankriks Frau und kehrt dann zu ihm nach Crossroads zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4941] = { title = "Eitriggs Weisheit", description = "Rend lebt?\n\nUnmöglich!\n\nEr soll doch schon vor Jahrzehnten getötet worden sein.\n\nBittet Etrigg, seine Weisheit mit Euch zu teilen, $N. Niemand kennt die Blackrock besser als er, und wenn es wahr ist, was hier geschrieben steht, muss Etrigg davon in Kenntnis gesetzt werden. Niemandem sollte das Recht auf Vergeltung versagt werden.\n\nIhr findet ihn in Orgrimmar.\n\nWenn Ihr mit Etrigg gesprochen habt, beratet Euch mit dem Kriegshäuptling, um von ihm zu erfahren, was er bezüglich dieses Problems zu unternehmen gedenkt.", objectives = "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.\n\nIhr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4961] = { title = "Die Säuberung der Kugel von Orahil", description = "Ah, eine Beschwörerkugel - sie muss die Quelle der Besudelung sein. Wir müssen erst den Dämon darin exorzieren, wenn Ihr sie benutzen wollt. Das ist ein Klacks für mich.\n\nIhr habt die schwere Aufgabe. Ihr müsst den Dämon töten, sobald ich ihn freigesetzt habe.\n\nUnd Ihr müsst Euch beeilen. Wenn Ihr zu lange braucht, kehrt er in die Kugel zurück und wir müssen von vorn anfangen!\n\nAlso macht Euch bereit, $n. Bereitet Eure stärksten Zauber vor, habt Eure Tränke parat und holt einen Freund, wenn Ihr einen habt. Denn das hier wird nicht angenehm.", objectives = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4962] = { title = "Splitter eines Teufelshundes", description = "Ihr seid also entschlossen, die Seele eines Teufelshundes zu fangen, gut.\n\nNehmt diesen Rubin - mit ihm könnt Ihr die Seele der Kreatur einfangen. Er funktioniert auf ähnliche Weise wie die Zauber, die Ihr bereits kennt: Wenn die Kreatur dem Tode nahe ist, benutzt den Edelstein, er sollte dann den Rest für Euch erledigen.\n\nIch schlage vor, dass Ihr nach Desolace geht und versucht, dort eines Teufelshundes habhaft zu werden. Die sollten geeignet sein.\n\nWenn Ihr Erfolg hattet, bringt den gefangenen Geist und Euren Rubin zu Menara.", objectives = "Nehmt den Felhas-Rubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Teufelshundgeist und den Felhas-Rubin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4963] = { title = "Splitter einer Höllenbestie", description = "Ihr seid also entschlossen, die Seele einer Höllenbestie zu fangen, gut.\n\nNehmt diesen Smaragd - mit ihm könnt Ihr die Seele der Kreatur einfangen. Er funktioniert auf ähnliche Weise wie die Zauber, die Ihr bereits kennt: Wenn die Kreatur dem Tode nahe ist, benutzt den Edelstein, er sollte dann den Rest für Euch erledigen.\n\nIch schlage vor, dass Ihr nach Desolace geht und versucht, dort einer Höllenbestie habhaft zu werden. Die sollten geeignet sein.\n\nWenn Ihr Erfolg hattet, bringt den gefangenen Geist und Euren Smaragd zu Menara.", objectives = "Nehmt den Infus-Smaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Höllenbestiengeist und den Infus-Smaragd.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4964] = { title = "Die fertig gestellte Kugel von Dar'Orahil", description = "Ich werde sofort mit der Arbeit an Eurer Kugel beginnen und Euren neuen Dämon darin einschließen. Wenn ich damit fertig bin, könnt Ihr entscheiden, ob Ihr ihn lieber in Form eines Stabs oder einer Kugel hättet. Ich fand es schon immer wichtig, dafür zu sorgen, dass jeder Hexenmeister die richtige Waffe bekommt ... Ich wüsste nicht, warum ich jetzt mit dieser Praxis aufhören sollte.", objectives = "Wartet, bis Menara Voidrender die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4965] = { title = "Wissen der Kugel von Orahil", description = "Schön, schön, schön... Es ist eine Freude zu sehen, wie Eure Macht wächst, $N. Ich würde sagen, dass Ihr bald bereit seid, im Brachland mit Menara Voidrender zu sprechen. Falls Ihr noch nie mit ihr gesprochen habt, dann lasst mich Euch sagen, dass ich wohl keinen zweiten Experten wie sie kenne, der so geschickt im Anfertigen von Gegenständen - insbesondere Kugeln - ist, in denen man sogar einen Dämon einkerkern kann, damit er einem einfach und bequem zu Diensten ist.\n\nFalls Ihr interessiert seid, begebt Euch zu Strahads Turm oberhalb von Ratchet im Brachland, dort findet Ihr sie.", objectives = "Sprecht mit Menara Voidrender im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4966] = { title = "Kanati Greycloud schützen", description = "Es könnte allerdings noch viel mehr Zentauren geben, als ich dachte, deshalb bitte ich Euch, $n, zusammen mit mir gegen diese gemeinen Auftragsmörder zu kämpfen.", objectives = "Beschützt Kanati Greycloud vor den Angriffen der Zentauren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4967] = { title = "Wissen der Kugel von Orahil", description = "Immer noch derselbe Dummkopf... und immer noch auf der Suche nach Dingen der Sterblichen. Ja, es mag Euch arrogant erscheinen, wie ich zu Euch spreche. Ihr steht vor mir und ich muss lachen. Ihr seid jämmerlich!\n\nAber was ich denke, zählt nicht. Es zählt nur, was jene denken, die gewillt sind, sich mit Euch abzugeben! Und obwohl ich anderer Ansicht bin, sind jene, die über ein gewisses Maß an Macht gebieten, der Meinung, dass Ihr mehr verdient.\n\nWenn es das ist, wonach Ihr trachtet, solltet Ihr mit Menara Voidrender im Turm oberhalb von Ratchet sprechen. Ich glaube, Ihr habt sie vor geraumer Zeit schon einmal getroffen.", objectives = "Sprecht mit Menara Voidrender im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4968] = { title = "Wissen der Kugel von Orahil", description = "Hmm, Ihr habt es also bis hierher geschafft... das ist wahrhaft erstaunlich. Ich dachte, die Verderbnis durch die Kanalisierung des Arkanen hätte sich mittlerweile in Eure Seele geschlichen und Euch in den Wahnsinn getrieben. Sollen wir versuchen, Euch noch ein bisschen weiter aufzubauen?\n\nWenn Ihr Eure Fertigkeiten auf die Probe stellen wollt, sprecht mit Menara Voidrender. Sie ist in Strahads Turm oberhalb von Ratchet zu finden. Sie wird Euch leiten.", objectives = "Sprecht mit Menara Voidrender im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4969] = { title = "Wissen der Kugel von Orahil", description = "Haha! Das habt Ihr sehr gut gemacht, $C.\n\nFrüher oder später werden sich selbst Höllenbestien und Schreckenslords vor Euch in den Staub werfen!\n\nAber bis dahin müsst Ihr Euch noch auf die Waffen verlassen, die von Sterblichen geschaffen wurden.\n\nIhr scheint bereit zu sein für ein weiteres solches Werk, und wenn Ihr möchtet, würde Menara Voidrender mit Euch sprechen! Sie ist in der Nähe von Strahads Turm zu finden, der oberhalb der Hafenstadt Ratchet steht. Geht dorthin, wenn Ihr bereit seid.", objectives = "Sprecht mit Menara Voidrender im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4970] = { title = "Frostsäblerverpflegung", description = "Wenn Ihr Euch beweisen wollt, könnt Ihr eine sehr einfache, aber sehr wichtige Aufgabe erledigen.\n\nSammelt Fleisch von der Schimäre und den Splitterzahnbären in diesem Gebiet. Bringt es mir, dann kann ich damit die Frostsäbler füttern, die gerade ausgebildet werden.", objectives = "Sammelt 5 Splitterzahnfleischstücke und 5 Fleischstücke einer Eiswindschimäre für Rivern Frostwind in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4971] = { title = "Eine Frage der Zeit", description = "Die Zeitlinie in Andorhal wurde durch eine finstere Kraft verfälscht - wahrscheinlich durch die Geißel! Ich kann versuchen, das Verstreichen der Zeit hier in den Griff zu bekommen und den Schaden zu beheben, aber dazu benötige ich Hilfe, damit ich dabei nicht gestört werde.\n\nTemporale Parasiten - Aas, das sich von den Strängen des veränderten Zeitflusses ernährt, sucht jetzt die Silos von Andorhal heim. Man kann sie nur an der blau pulsierenden Verzerrung erkennen. Sie behindern meine Weissagungen. Bitte helft mir, $n, indem Ihr diesen Temporalversetzer benutzt, um diese Parasiten auszurotten.", objectives = "Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.\n\nTötet 15 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4972] = { title = "Tempus fugit", description = "Ich müsst für mich in die jenseits dieses Raumes liegende Welt gelangen, $N. Lasst es mich Euch erklären.\n\nIhr seht, dass dieser Raum hier anders ist als der Rest von Andorhal. Mein Drachenschwarm agiert auf verschiedene Weise und in vielen verschiedenen Zeitlinien. Um den in Andorhal angerichteten Schaden zu beheben, handle ich jetzt von einer anderen Zeitlinie aus, um sie nicht allzu sehr zu kontaminieren. Um diese Arbeit fortzusetzen, benötige ich Zeitobjekte, die aus einer Zeit stammen, bevor die Seuche auftrat. Ihr findet sie in Schließkassetten in den Ruinen der Gebäude, die einst diese stolze Stadt waren.", objectives = "Sucht 5 Andorhal-Uhren, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4973] = { title = "Tempus fugit", description = "Falls Ihr gewillt seid, mir noch einmal zu helfen, würde ich Eure Unterstützung dankbar annehmen. Ich nehme Euch gern weitere Uhren ab, die Ihr in den Ruinen von Andorhal findet. Sie helfen mir sicherlich dabei, das Gleichgewicht gegen die unbekannte bösartige Kraft zu erhalten, die hier mit der Zeitlinie herumspielt.\n\nIm Austausch für diese Uhren werde ich Euch einen anderen Gegenstand geben, der sich, wie ich vermute, in der Zukunft für Euch als von großem Wert erweisen wird.", objectives = "Sucht 5 Andorhal-Uhren in den Ruinen der Stadt und bringt sie Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4974] = { title = "Für die Horde!", description = "Nur weil der schwarze Drachenschwarm hinter ihm steht, wagt Rend es, solche Ansprüche zu stellen.\n\nIhr, $N, müsst einen Weg finden, die Hallen des Aufstiegs zu durchqueren. Dahinter findet Ihr den 'Kriegshäuptling' Rend Blackhand. Ihr müsst ihn vernichten... FÜR DIE HORDE!\n\n<Thrall schlägt mit der Faust auf seinen Thron.>\n\nWenn Ihr meine Gemächer das nächste Mal betretet, werdet Ihr seinen Kopf triumphierend in die Höhe halten und ihn Eurem Kriegshäuptling präsentieren. Gelingt Euch das, wird man Euch als Held der Horde ehren.", objectives = "Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4975] = { title = "Die fertig gestellte Kugel von Noh'Orahil", description = "Ich werde sofort mit der Arbeit an Eurer Kugel beginnen und Euren neuen Dämon darin einschließen. Wenn ich damit fertig bin, könnt Ihr entscheiden, ob Ihr ihn lieber in Form eines Stabs oder einer Kugel hättet. Ich fand es schon immer wichtig, dafür zu sorgen, dass jeder Hexenmeister die richtige Waffe bekommt ... Ich wüsste nicht, warum ich jetzt mit dieser Praxis aufhören sollte.", objectives = "Wartet, bis Menara Voidrender die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4976] = { title = "Ablieferung der gesäuberten Kugel", description = "Bringt die gesäuberte Kugel zurück zu Menara nach Ratchet, $N. Grüßt sie von mir und passt auf Euch auf. Ich hoffe wirklich, dass Ihr der Versuchung und der Verderbnis widerstehen könnt, die Euch auf Eurem Weg sicherlich begleiten werden.\n\nViel Glück.", objectives = "Bringt die gesäuberte Höllenkugel zu Menara Voidrender ins Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4981] = { title = "Agentin Bijou", description = "Trau niemals einem Goblin. Darauf läuft es doch hinaus, $N.\n\nSie heißt Bijou und ist eine unserer unzuverlässigsten Agentinnen. Ich habe herausgefunden, dass sie für irgendeinen zwielichtigen Tierhändler namens Kibler außerhalb der brennenden Steppe gearbeitet hat - sie hat uns schlicht und ergreifend hintergangen. Und was noch schlimmer ist, sie hat Gelder der Horde veruntreut, um ihre Machenschaften zu finanzieren.\n\nIch will, dass man sie mir lebend bringt!\n\nZuletzt wurde sie beim Betreten der Blackrockspitze gesehen. Findet sie und bringt sie her.\n\nUnd lasst Euch bloß nicht von ihr umgarnen, $N.", objectives = "Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4982] = { title = "Bijous Habseligkeiten", description = "Nachts, wenn dieser Ort hier nur leicht bewacht ist, schleiche ich durch die Stadt, mache mir Notizen und schreibe alles auf, was für das KEK strategisch nützlich sein könnte.\n\nLetzte Nacht ist allerdings etwas fürchterlich schief gegangen. Ich bin über einen Stolperdraht getappt und habe einen Alarm ausgelöst. Also habe ich mein Spionagezeug versteckt und bin auf Tauchstation gegangen! Leider kann ich nicht zurück, um meine Ausrüstung zu holen. Sie haben die Patrouillen verdoppelt und verdreifacht! All diese Informationen sind verloren.\n\nHolt mir meine Habseligkeiten, dann kehre ich freiwillig zum KEK zurück.", objectives = "Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4983] = { title = "Bijous Aufklärungsbericht", description = "Bringt Lexlort diesen Bericht. Er wird meinen Namen reinwaschen und dem KEK bestimmt einen strategischen Vorteil gegenüber diesen Orcs verschaffen.\n\nIch soll mit Euch kommen? Dafür habe ich noch viel zu viel zu tun. Geht jetzt, diese Berichte werden gebraucht, je eher, desto besser!", objectives = "Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4984] = { title = "Die Tierwelt leidet auch", description = "Allein konnte ich nicht viel tun, um die Geißel zu bezwingen. Aber ich kam dennoch hierher, um zu versuchen, den an der Natur angerichteten Schaden zu lindern. Die Tiere leiden unter der Seuche, die das Land noch immer plagt, und finden weder Gnade noch Frieden. Ich bitte Euch fortzusetzen, was ich hier nicht beenden konnte.\n\nEs gibt für diese leidenden Tiere keine Rettung, nur eine gnädige und sanfte Erlösung. Sucht die kranken Wölfe auf, die sich hier in der Nähe befinden, und tötet sie. Bitte, $n, macht ihrem Leiden ein Ende - Ihr würdet damit auch meinen Kummer lindern.", objectives = "Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4985] = { title = "Die Tierwelt leidet auch", description = "Östlich von hier, etwa da, wo die Östlichen Pestländer beginnen, streiften einst stolze und herrliche Grizzlys durch das Land. Die von der Geißel freigesetzte Seuche hat auch auf diese Wildtiere übergegriffen. Jetzt ziehen sie durchs Land und leiden sehr, während ihre Muskeln steif werden und ihr Fell und Fleisch langsam verrotten.\n\nIch bitte Euch, auch sie von ihrem Elend zu erlösen. Das einzige Heilmittel für sie ist ein schneller Tod, beigebracht durch Eure Hand.", objectives = "Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4986] = { title = "Glyphenverzierter Eichenast", description = "Die leblose Hand des Tauren hält einen erstaunlich gesund aussehenden Eichenast umklammert. Als Ihr den Ast untersucht, entdeckt Ihr Glyphen druidischer Art, die in die Rinde geritzt sind.\n\nIhr nehmt den Ast und stellt fest, dass er sich warm anfühlt. Viel wärmer, als er sich anfühlen sollte. Vor Eurem inneren Auge erscheint das Bild des Teldrassil-Baumes - genau gesagt von Darnassus - und die Worte \"Zirkel des Cenarius\" liegen Euch auf der Zunge. Es scheint, als hätte man dem Ast die Information mitgegeben wohin er zu bringen sei.", objectives = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[4987] = { title = "Glyphenverzierter Eichenast", description = "Die leblose Hand des Tauren hält einen erstaunlich gesund aussehenden Eichenast umklammert. Als Ihr den Ast untersucht, entdeckt Ihr Glyphen druidischer Art, die in die Rinde geritzt sind.\n\nIhr nehmt den Ast und stellt fest, dass er sich warm anfühlt. Viel wärmer, als er sich anfühlen sollte. Vor Eurem inneren Auge erscheint das Bild von Thunder Bluff in Mulgore - genau gesagt von der Anhöhe der Ältesten - und die Worte \"Zirkel des Cenarius\" liegen Euch auf der Zunge. Es scheint, als hätte man dem Ast die Information mitgegeben, wohin er zu bringen sei.", objectives = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Thunder Bluff bringt. Bittet einen der Druiden dort um Hilfe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5001] = { title = "Bijous Habseligkeiten", description = "Normalerweise gebe ich mich nicht mit Euresgleichen ab, $R, aber mir scheint, ich stecke hier in einer Zwickmühle. Wisst Ihr, meine Mission hier ist für die Horde von allergrößter Wichtigkeit. Die Informationen, die ich hier gesammelt habe, betreffen jedoch auch das Wohlergehen der Allianz. Ihr könnt mir glauben, ich bin wahrlich kein Freund der Allianz, aber die Gefahr durch die Blackrock ist größer als nur ein Haufen Orcs.\n\nIhr helft mir, meine Habseligkeiten zu finden, dann helfe ich Euch mit ein paar Informationen aus, die sich für Euresgleichen als nützlich erweisen könnten.\n\nAbgemacht?", objectives = "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5002] = { title = "Nachricht an Maxwell", description = "Ich bin ein Goblin, der zu seinem Wort steht, $R. Und jetzt hört gut zu.\n\nDiese Orcs werden vom schwarzen Drachenschwarm vor allem als Packesel und Kanonenfutter missbraucht!\n\nIhr wahrer Anführer ist kein Geringerer als Nefarian, die Brut von Deathwing. Ich habe auch den Aufenthaltsort der Untergebenen von Nefarian in diesem Teil der Zitadelle entdeckt.\n\nBringt diese Karte zu Marshal Maxwell in der brennenden Steppe. Auf ihr ist der Aufenthaltsort dieser Teufelskreaturen eingezeichnet, um es einfacher zu machen.", objectives = "Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marshal Maxwell weiter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5021] = { title = "Besser spät als nie", description = "Das Paket muss ausgeliefert werden... sonst bin ich hier gefangen!\"\n\nWie ein Flüstern zieht das Wehklagen einer verängstigten Frau durch das Haus. In einer Ecke im oberen Stockwerk kauert eine weibliche, geisterhafte Gestalt. Sie scheint sich ihrer Umgebung nicht ganz gewahr zu sein und ist sich Eurer nur vage bewusst.\n\n\"Seid Ihr hier, um mein Paket auszuliefern? Bitte, bevor es noch viel schlimmer wird! Ich wollte hier wegreiten. Es sollte immer noch bei meinem Pferd sein... oder komme ich zu spät?", objectives = "Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5022] = { title = "Besser spät als nie", description = "Ihr hebt das Paket auf und wischt eine dünne Schicht aus Staub und Schmutz ab, mit der es bedeckt ist. Es ist mit hastig hingekritzelter Schrift an eine Emma Felstone in Stormwind adressiert; die Auslieferung des Pakets war für einen Tag vor über vier Jahren geplant.\n\nOb Emma Felstone überhaupt noch lebt, ist nicht klar. Aber man weiß, dass im Rathaus von Stormwind Unterlagen über die Bevölkerung der Stadt aufbewahrt werden. Sie werden von den königlichen Disponenten des Volkszählungsbüros von Stormwind verwaltet.", objectives = "Wendet Euch an die königlichen Disponenten von Stormwind, um etwas über den Aufenthaltsort von Emma Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5023] = { title = "Besser spät als nie", description = "Ihr hebt das Paket auf und wischt eine dünne Schicht aus Staub und Schmutz ab, mit der es bedeckt ist. Es ist mit hastig hingekritzelter Schrift an einen Jeremiah Felstone aus Lordaeron adressiert; die Auslieferung des Pakets war für einen Tag vor über vier Jahren geplant.\n\nOb Jeremiah Felstone überhaupt noch lebt, ist nicht klar. Aber man weiß, dass Undercity, früher bekannt als Lordaeron, Unterlagen über die Bevölkerung der Stadt aufbewahrt. Sie werden von den königlichen Vorarbeitern des Volkszählungsbüros von Undercity verwaltet.", objectives = "Wendet Euch an die königlichen Vorarbeiter von Undercity, um etwas über den Aufenthaltsort von Jeremiah Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter in der Nähe der Gilden- und Wappenrock-Registrierung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5041] = { title = "Vorräte für Crossroads", description = "Die Karawane, die angegriffen wurde, führte Vorräte mit sich, die wir dringend benötigen.\n\nIhr wart bisher tapfer genug, den Grimmhauerstamm zu bekämpfen, und ich werde Euch bitten, es erneut zu tun. Dieses Mal wüsste ich aber gern, ob ich Euch bitten könnte, nach unseren verlorenen Vorräten Ausschau zu halten. Ihr könnt sie wahrscheinlich in ihren Lagern finden; die Stacheleber werden durch ihre schändlichen Taten fett.\n\nDie Einwohner von Crossroads wären in Eurer Schuld.", objectives = "Findet die Crossroads-Vorratskisten und bringt sie zu Thork im Brachland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5042] = { title = "Agammagans Kraft", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5043] = { title = "Agammagans Beweglichkeit", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5044] = { title = "Weisheit von Agammagan", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5045] = { title = "Steigerung des Geistes", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5046] = { title = "Klingenhaut", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5047] = { title = "Finkle Einhorn, zu Euren Diensten!", description = "Ihr findet Malyfous Darkhammer in Everlook, $C. Sagt ihm, dass Finkle absolut in Ordnung ist und dass der Anzug perfekt funktioniert.\n\nDann gebt ihm dies:\n\n<Finkle gibt Euch ein leuchtendes Fleischstück.>\n\nIch riss es aus den Innereien des Viechs während meines 'Urlaubs.'\n\nIch wette Malyfous könnte Euch eine recht genaue Einschätzung dessen geben, was er mit Teilen eines solchen Monsters tun kann!\n\nOh, ich schätze Ihr wisst nicht, wo Everlook ist, was? Geht nach Winterspring, $g Bursche:Mädel;!", objectives = "Sprecht mit Malyfous Darkhammer in Everlook.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5048] = { title = "Emma die Nette", description = "Sie ist ein bisschen zänkisch und vielleicht nicht so ganz richtig im Kopf... aber diese Akten deuten darauf hin, dass die alte Emma zu den Informationen passt, die wir über Emma Felstone haben.\n\nVielleicht habt Ihr die alte Emma durch die Stadt streifen sehen... sie redet mit sich selbst, meistens sinnloses Geplapper. Sie tut aber nichts und niemandem weh, also lassen die Leute sie meist gewähren.\n\nAlles in allem würde ich sagen, dass die alte Emma tatsächlich Emma Felstone ist. Ihr könntet sie fragen, ob ihr Nachname Felstone ist.", objectives = "Sucht die alte Emma in Stormwind und findet heraus, ob sie tatsächlich Emma Felstone ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Felstone für sie gepackt hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5049] = { title = "Der Jammer des Jeremiah", description = "Nach den Informationen, die ich finden konnte, ist die Person, die Ihr sucht - und der vorgesehene Empfänger des Pakets -, Jeremiah Payson, der Kakerlakenverkäufer von Undercity.\n\nIch war immer der Meinung, dass es einer besonderen Gabe bedarf, um... Kakerlaken zu verkaufen. Zweifellos seid Ihr jetzt auf einer recht epischen Reise, $C. Ich werde Euch Euren weltverändernden Bestrebungen überlassen. Erlaubt mir aber, ein Teil Eures Meisterwerks zu sein und zu enthüllen, dass er sich in der Nähe der Bank aufhält und unter einem der Gehwege herumkriecht.", objectives = "Sucht Jeremiah Payson in Undercity und findet heraus, ob er tatsächlich Jeremiah Felstone ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Felstone für ihn gepackt hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5050] = { title = "Glücksbringer", description = "Es scheint, dass ich bei Euch falsch lag, $N, und dafür schulde ich Euch eine Entschuldigung. Meine Schwester hat einige persönliche Dinge geschickt, einschließlich, was witzig genug ist, die Urkunde zum Teufelssteinfeld. Ich denke, ich werde im Moment darauf verzichten, ihn zu beanspruchen.\n\nWenn der Geist meiner Schwester weiterhin an den Hof gebunden ist und keine Ruhe finden kann, bitte ... könntet Ihr dies wohl zu ihr bringen? Es ist die Hälfte eines Glücksbringers, den sie einst hatte. Die andere Hälfte hatte ihr Ehemann.\n\nVielleicht wird sie ihren Frieden finden, wenn sie weiß, dass ich diese Dinge habe.", objectives = "Bringt Janice Felstone in den Westlichen Pestländern die Hälfte ihres Glücksbringers zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5051] = { title = "Zwei Hälften vereint", description = "Der arme Geist plappert weiter:\n\n\"Mir ist so kalt, John. Bring mir deinen Glücksbringer und wir werden vereint sein! Schnell, John, bevor die Seuche uns in grauenhafte Bestien verwandelt! Ich kann dich nicht sehen, John... aber ich weiß, dass du nah bist. Ich fühle dich in meiner Nähe.\"\n\nVielleicht solltet Ihr die zweite Hälfte des Glücksbringers suchen und das Amulett wieder zusammensetzen... es könnte sein, dass der Geist von Janice Felstone genau das sucht.", objectives = "Sucht auf dem Teufelssteinfeld in den Westlichen Pestländern nach der anderen Hälfte des Glücksbringers und setzt ihn wieder zusammen.\n\nGebt den Glücksbringer Janice Felstone auf demTeufelssteinfeld in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5052] = { title = "Blutsplitter von Agammagan", description = "Zusammen mit diesen Dornen wirkte sich das Blut <schnaubt> auf andere Aspekte der Erde aus: blutrote Steine gemischt mit anderen Mineralien. Die Borstennacken graben diese Splitter aus und tragen sie als Totems <schnaubt> für Kraft im Kampf und als Totems für ihre Magie. <schnaubt>\n\nIch kenne die Geheimnisse dieser Magie.\n\nBringt Quetschzahn einen dieser Blutsplitter, um zu zeigen, dass Ihr verstanden habt. Bringt Quetschzahn viele dieser Splitter und er wird Euch mit Stachelebermagie segnen - der Magie von Agammagan! <schnaubt>", objectives = "Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter.\n\nSammelt weitere Blutsplitter, wenn Ihr von ihm mit Agammagans Macht gesegnet werden möchtet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5054] = { title = "Ursius von den Splitterzahnbären", description = "In den schneebedeckten Bergen von Winterspring pirscht sich ein geschickter Jäger an seine Beute an... Ich spreche vom Splitterzahnbären Ursius, einer flinken und schlauen Bestie.\n\nIch schicke Euch nun gegen ihn. Er zieht durch die wogenden Hügel im Nordwesten von Everlook. Findet und jagt ihn, bevor er Eure Absicht erkennt.\n\nAlle, die bisher gegen Ursius gezogen sind, haben schnell herausgefunden, dass sie die Beute waren und er der Jäger. Also seht Euch vor.", objectives = "Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Ursius tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5055] = { title = "Brumeran von den Eiswindschimären", description = "Geschickt und schlau gleitet Brumeran leise über die schneebedeckte Landschaft des südlichen Winterspring. Lasst Euch aber nicht von Ihrem graziösen Auftreten verleiten zu glauben, dass sie harmlos sei. Alle, die ihren Weg kreuzen, bezahlen einen hohen Preis dafür und häufig mit ihrem eigenen Leben.\n\nSucht Brumeran von den Eiswindschimären. Besiegt sie und kehrt dann wieder zu mir zurück.", objectives = "Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Brumeran tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5056] = { title = "Shy-Rotam", description = "Im nördlichen Winterspring sammeln sich große Katzen rund um einen großen Orientierungspunkt, dem Frostsäblerfelsen. Die Anführerin dieser Katzen ist unter dem Namen Shy-Rotam bekannt. Wenn Ihr die Matriarchin der Frostsäbler besiegen würdet, würde Euch das großen Respekt in den Augen der anderen $R einbringen.\n\nGeht erneut nach Winterspring und sammelt dort hochheiliges Fleisch von den Frostsäblern. Sucht den Stein von Shy-Rotam und legt das Fleisch dort ab. Wenn Ihr es dort platziert, ruft das Shy-Rotam herbei... und sie wird kochen vor Wut.\n\nWappnet Euch vor ihrem Zorn und besiegt sie.", objectives = "Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Shy-Rotam besiegt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5057] = { title = "Frühere Abenteuer", description = "Schon bevor Ihr mit mir spracht, $N, habe ich von Euren Abenteuern gehört... dass Ihr den unerschütterlichen Willen habt, Euch selbst zu beweisen, und dass Ihr als $C außerordentliche Fähigkeiten besitzt. Und nun weiß ich, dass diese Dinge wahr sind.\n\nWer wie Ihr herausragt, ist der Anerkennung würdig. Bringt diesen Gutschein zu einem Freund von mir in Thunder Bluff namens Melor Stonehoof. Ich bin sicher, dass er sich an Euch und das, was Ihr vor so langer Zeit erreicht habt, erinnern wird. Sprecht mit ihm über Eure jüngsten Siege und vergesst nicht, was Ihr heute erreicht habt.", objectives = "Bringt Storm Shadowhoofs Gutschein zu Melor Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5058] = { title = "Mrs. Dalsons Tagebuch", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5059] = { title = "Weggeschlossen", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5060] = { title = "Weggeschlossen", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5061] = { title = "Wassergestalt", description = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Mathrengyl Bearwalker nach Darnassus zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.\n\nAuf Wiedersehen. Wir werden uns wieder sprechen.", objectives = "Kehrt nach Darnassus zurück und zeigt Mathrengyl Bearwalker den Anhänger des Seelöwen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5062] = { title = "Hochheiliges Feuer", description = "Arikara ist eine tödliche Kreatur, die schnell beseitigt werden muss. Um sie zur Strecke zu bringen, müsst Ihr das hochheilige Feuer des Lebens anzünden - so wird Arikara beschworen.\n\nGeht nun und holt eine seltene Pflanze, die Brandpulveragave. Wenn Ihr genug Agaven gesammelt habt, sucht den Rat von Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff. Sie ist eine mächtige Schamanin, die die Agavenpflanze verzaubern kann, um ein Pulver zu erzeugen, das das Feuer entzünden kann.\n\nReist in Richtung Osten zum Siedenden Teich und sammelt Brandpulveragaven.", objectives = "Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5063] = { title = "Kappe des Scharlachroten Wissenden", description = "Eine feinere Kappe werdet Ihr niemals sehen. Aus dem makellosen Balg der Bestie werden unsere Experten den phänomenalsten Hut schaffen, den ein Gaukler jemals zu tragen träumte!\n\nFünfzig Goldstücke zusammen mit den aufgeführten Gegenständen und Euer Kopf wird von der Kappe des Scharlachroten Wissenden geziert:\n\n*Einen makellosen Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkankristalle.\n\n*Verzauberter scharlachroter Faden.\n\nMERKT AUF!", objectives = "Um die Kappe des scharlachroten Wissenden herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 8 Arkankristalle; 5 verzauberte scharlachrote Fäden.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5064] = { title = "Grimmtotemspionage", description = "$n, Ihr habt uns in der Vergangenheit gut gedient, sodass ich Euch jetzt eine wichtige Mission anvertraue. Der Grimmtotemklan plant etwas, das niemand wissen soll. Drei Agenten unbekannter Herkunft wurden gesehen, wie sie die Grimmtotem in den vergangenen Wochen besuchten. Wir haben entdeckt, dass diese geheimnisvollen Botschaften im Düsterwolkengipfel in verschiedenen Truhen verwahrt werden.\n\n$n, wenn Ihr bei dieser gefährlichen Mission erfolgreich seid, werde ich Euch entsprechend belohnen.", objectives = "Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5065] = { title = "Die verlorenen Schrifttafeln von Mosh'aru", description = "Der Troll, mit dem Ihr gesprochen habt, hat Euch nicht die Wahrheit gesagt. Die beiden Schrifttafeln, die Ihr von ihm erhalten habt, sprachen davon, die Essenz von Hakkar zu bewahren, aber an dieser Legende ist noch mehr. Ich habe sie lange studiert und herausgefunden, dass es sechs Schrifttafeln von Mosh'aru gibt, nicht zwei! Sechs!\n\nUnd ich fürchte, dass uns die Geheimnisse, die die anderen enthalten, nicht gefallen werden.\n\nSucht die dritte und vierte Schrifttafel von Mosh'aru. Sie befinden sich in den Östlichen Pestländern, im Besitz der Moosschindertrolle. Sucht sie und bringt sie mir.", objectives = "Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5066] = { title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Stormwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Valorfist auf, der seinen Stützpunkt an der Chillwindspitze errichtet hat, nördlich des Alteracgebirges!", objectives = "Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5067] = { title = "Gamaschen von Arcana", description = "Wenn die Herstellung eines solchen Gegenstandes auch noch nie erfolgreich bewerkstelligt wurde, so wird sie doch für möglich erachtet - unter den richtigen Umständen.\n\nSollte der Sucher des Arkanums wünschen, Gamaschen mit immenser Kraft magiezuerfüllen, so muss er Folgendes suchen:\n\n*Einen makellosen Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkanitbarren.\n\n*Frostraunens Balsamierungsflüssigkeit.\n\nMERKT AUF!", objectives = "Um die Gamaschen von Arcana herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Einheiten Frostraunens Balsamierungsflüssigkeit.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5068] = { title = "Brustplatte des Blutdurstes", description = "Es heißt, dass nur eine einzige Brustplatte des Blutdurstes jemals geschaffen wurde und dass sie für die legendäre Auftragsmörderin Garona gemacht wurde. Ob diese Welt jemals eine weitere sehen wird, ist zu bezweifeln.\n\nWie dem auch sei! Unsere meisterlichen Handwerker können den Gegenstand reproduzieren, wenn die notwendigen Komponenten vorhanden sind:\n\n*Ein makelloser Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkanitbarren.\n\n*Die Haut des Schattens.\n\nMERKT AUF!", objectives = "Um die Brustplatte des Blutdurstes herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 10 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Häute des Schattens.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5081] = { title = "Maxwells Mission", description = "Diese Informationen füllen die Lücken in unseren sonst einwandfreien Geheimdienstdaten über die Blackrockspitze.\n\nDer Angriff muss entscheidend sein, $N.\n\nZuerst muss ihr Kriegsmeister, der Troll Voone, vernichtet werden. Ohne seine Kampfpläne werden die Blackrockorcs im Chaos versinken.\n\nDann müsst Ihr den Ogerhochlord Omokk ausschalten. Die feigen Oger von Blackrock sind ohne seine Führungskraft machtlos.\n\nSchließlich noch der Oberanführer der Zitadelle: Wyrmthalak. Wenn Wyrmthalak tot ist, ist ihre zentrale Kommandoeinheit ohne Leitung.", objectives = "Reist zur Blackrockspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5082] = { title = "Bedrohung durch die Winterfelle", description = "Ich kam nach Winterspring, um die heißen Quellen von Frostfire zu untersuchen. Mir ist aufgefallen, dass das Wasser... merkwürdige Eigenschaften zu haben scheint. Ich konnte die Quelle aber noch nicht entdecken, und um die Wahrheit zu sagen, hatte ich in letzter Zeit durch die Furbolgs der Winterfelle einige Schwierigkeiten.\n\nSie scheinen von den Quellen angezogen zu werden, genau wie ich. Mittlerweile wachen sie extrem eifersüchtig über das Wasser und lassen mich nicht einmal in die Nähe der beiden größeren Quellen, die von hier aus im Norden liegen.\n\nIch würde meine Studien aber gern fortsetzen. Könntet Ihr mir wohl helfen?", objectives = "Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5083] = { title = "Feuerwasser der Winterfelle", description = "Diese Phiole, die Ihr bei den Winterfellfurbolgs aufgehoben habt, ist leer, aber Ihr könnt im Inneren ein paar Tropfen einer merkwürdigen grünen Flüssigkeit sehen; sie scheint fast zu glühen.\n\nIst es etwas Wichtiges?\n\nDonova Snowden könnte Euch wahrscheinlich mehr sagen, da sie nun schon einige Zeit bei den heißen Quellen in Winterspring lagert.", objectives = "Bringt das leere Feuerwasserfläschchen zu Donova Snowden in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5084] = { title = "Der Verderbnis erliegen", description = "Diese grünliche Flüssigkeit... sie erinnert mich ein wenig an den Schlamm, den ich bei meiner Reise durch den Teufelswald sah. Und ich habe einige Läufer der Winterfelle gesehen, die die Furbolgs der Holzschlundfeste passierten... Vielleicht haben diese Dinge etwas mit dem Fläschchen zu tun, das Ihr gefunden habt, $N.\n\nEs gibt eine große Gruppe Furbolgs direkt hinter der Holzschlundfeste im Teufelswald. Es ist der so genannte Stamm der Totenwaldfelle. Er wurde durch den Fel verderbt und in den Wahnsinn getrieben. Warum seht Ihr Euch dort nicht um und schaut, ob Ihr Beweise für irgendwelche Beziehungen zwischen den Winterfellfurbolgs und den Totenwaldfellen findet?", objectives = "Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5085] = { title = "Geheimnisvoller Glibber", description = "Die grünliche Substanz in dem Kessel scheint der zu ähneln, die Ihr in dem Fläschchen gefunden habt. Dieses merkwürdige zähflüssige Zeug könnte genauso verderbt sein wie die Furbolgs, die es geschaffen haben...\n\nFalls die Winterfellfurbolgs es verwenden, bedeutet das, dass sie bald genauso verderbt sein werden wie der Stamm der Totenwaldfelle?\n\nEs wäre das Beste, Donova von Euren Funden zu berichten und ihr eine Probe aus dem Kessel mitzubringen.", objectives = "Berichtet Donova Snowden von Euren Entdeckungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5086] = { title = "Toxinschrecken", description = "Ich habe die Probe untersucht, die Ihr mitgebracht habt. Ganz sicher bin ich mir nicht, aber ich glaube doch, dass sie Spuren von toxischen Elementen enthält. Die einzige Möglichkeit, das zu bestätigen, besteht darin, einige Proben als Vergleich zu sammeln.\n\nIch glaube, dass sich die Furbolgs der Totenwaldfelle diese Elemente möglicherweise von anderen verderbten Kreaturen im Teufelswald holen, vor allem von den Elementaren, die im Eisenwald leben und Toxinschrecken genannt werden.\n\nSammelt einige Proben zum Vergleich für mich. Aber seid vorsichtig: Es ist dort sehr gefährlich!", objectives = "Sammelt 3 Toxinschrecken-Tröpfchen für Donova Snowden in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5087] = { title = "Läufer der Winterfelle", description = "Sehr interessant, $n...\n\nWenn diese toxische Substanz mit dem Wasser aus den heißen Quellen gemischt wird, verliert sie ihre Toxizität und behält lediglich die Fähigkeit zurück, Kreaturen vorübergehend zu beeinflussen, die sie einnehmen. Darum verteidigen die Winterfelle die heißen Quellen wohl so vehement - sie brauchen sie, um ihr Feuerwasser zu läutern.\n\nWir müssen das hier stoppen... den Kontakt zwischen den Winterfellen und den Totenwaldfellen abschneiden. Eine Gruppe von Läufern ist zwischen ihrem Dorf und dem Teufelswald unterwegs. Sucht und besiegt sie und stehlt ihre Lieferung.", objectives = "Sucht die Läufer der Winterfelle und hindert sie daran, ihre Lieferung zum Lager der Winterfelle zu bringen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5088] = { title = "Arikara", description = "Bringt dieses aufbereitete und geläuterte Brandpulver nach Tausend Nadeln und werft es in das hochheilige Feuer des Lebens. Es befindet sich beim Düsterwolkengipfel auf einer isolierten Nadel, wo sie ihre Toten beerdigen.\n\nDie Verzauberung, die ich in das Brandpulver eingewoben habe, wird Arikara für Euch beschwören, $N.\n\nIch fürchte, dass sie Cairne Bloodhoof bedrohen könnte; die Lehren der Tauren haben sich zu sehr verändert und möglicherweise ist Arikara darüber erzürnt. Tut schnell etwas, bevor alles verloren ist, $C!", objectives = "Erschlagt Arikara. Bringt ihre Überreste und das Brandpulver zu Motega Firemane im Weißgipfelposten als Beweis für Eure Tat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5089] = { title = "General Drakkisaths Befehl", description = "Dem Kadaver der besiegten Schlange entnehmt Ihr etwas, das wie ein Schreiben von einiger Bedeutung aussieht. Es ist ein Brief des Vorgesetzten, General Drakkisath, bezüglich des Protokolls.\n\nEuer Instinkt sagt Euch, dass Ihr ihn zu Marshal Maxwell bringen solltet.", objectives = "Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5090] = { title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Stormwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Valorfist auf, der seinen Stützpunkt an der Chillwindspitze errichtet hat, nördlich des Alteracgebirges!", objectives = "Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5091] = { title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Stormwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Valorfist auf, der seinen Stützpunkt an der Chillwindspitze errichtet hat, nördlich des Alteracgebirges!", objectives = "Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5092] = { title = "Den Weg räumen", description = "Da die westlichen und nördlichen Straßen in die Stadt von Andorhal gut befestigt sind, habe ich vor, über die weniger gut verteidigte östliche Straße anzugreifen. Die Geißel verlässt sich auf den Puffer von Untoten, die Sorrow Hill heimsuchen, als erste Verteidigungslinie. Wenn wir nach Andorhal vordringen wollen, müssen wir es über Sorrow Hill tun.\n\nEure erste Aufgabe besteht darin, den Weg durch Sorrow Hill zu säubern. Dünnt die Masse der Skelette und Ghuls aus, die das Gebiet heimsuchen. Meldet Euch wieder bei mir, wenn das erledigt ist!", objectives = "Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill.\n\nKehrt zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5093] = { title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der östlichen Königreiche erheben! Sie lauern östlich von Undercity, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunk am Bollwerk östlich von Tirisfal aufgeschlagen!", objectives = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5094] = { title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der östlichen Königreiche erheben! Sie lauern östlich von Undercity, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunk am Bollwerk östlich von Tirisfal aufgeschlagen!", objectives = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5095] = { title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Ihr Helden dieser Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der östlichen Königreiche erheben! Sie lauern östlich von Undercity, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nZögert nicht lange, ihr Helden! Sucht Hochexekutor Derrington auf! Er hat seinen Stützpunk am Bollwerk östlich von Tirisfal aufgeschlagen.", objectives = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5096] = { title = "Scharlachrote Ablenkung", description = "Vor Andorhal müssen wir die Bedrohung durch den anrückenden Scharlachroten Kreuzzug von Hearthglen niederschlagen. Dessen Lager wurde zwischen dem Teufelssteinfeld und Dalsons Tränenfeld aufgeschlagen, wodurch wir gleichzeitig einen Konflikt mit der Geißel und dem Kreuzzug riskieren müssen.\n\nMein Plan ist, sie gegeneinander auszuspielen, indem wir Euch schicken, um das Kommandozelt zu zerstören, das sie errichtet haben. Benutzt dazu die Flaschenflammen aus dieser Kiste mit Brandsätzen. Sobald es vernichtet ist, richtet Ihr dieses Banner der Geißel bei dem Zelt auf. Mit etwas Glück werden sie uns ignorieren und sich auf Rache gegen die Geißel konzentrieren.", objectives = "Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt.\n\nLasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5097] = { title = "Turm um Turm", description = "Durch die Verwendung eines magischen Gegenstandes, einer Signalfackel, können wir Ziele unserer Wahl für künftige Aktionen durch unsere Truppen markieren. Was das angeht, glauben wir, dass die Geißel die Wachtürme von Andorhal nutzt, um die Bewegungen ihrer Truppen zu kontrollieren.\n\nEure Mission: Durchbrecht die Verteidigung von Andorhal, um Signalfackeln an allen vier Wachtürmen zu platzieren. Ihr müsst im Eingang eines jeden Turmes stehen, um das Signal zu platzieren; es wird dann den Turm markieren. Die Signalfackel hat nur fünf Ladungen, nutzt sie also weise!", objectives = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\n\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5098] = { title = "Turm um Turm", description = "Durch die Verwendung eines magischen Gegenstandes, einer Signalfackel, können wir Ziele unserer Wahl für künftige Aktionen durch unsere Truppen markieren. Was das angeht, glauben wir, dass die Geißel die Wachtürme von Andorhal nutzt, um die Bewegungen ihrer Truppen zu kontrollieren.\n\nEure Mission: Durchbrecht die Verteidigung von Andorhal, um Signalfackeln an allen vier Wachtürmen zu platzieren. Ihr müsst im Eingang eines jeden Turmes stehen, um das Signal zu platzieren; es wird dann den Turm markieren. Die Signalfackel hat nur fünf Ladungen, nutzt sie also weise!", objectives = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\n\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk, Westliche Pestländer, zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5102] = { title = "General Drakkisaths Niedergang", description = "Wir kämpfen an zwei Fronten gegen diese Biester: Von unserer Hauptstadt Stormwind aus bekämpfen wir sie von innen, und hier, in der brennenden Steppe, tragen wir den Kampf an ihre Türschwelle. Wir müssen wachsam sein, $N. Niemand soll von unserem Zorn verschont werden, da keiner der Unseren verschont wurde, als der Feind bei unseren Heimen und Familien zuschlug.\n\nFindet diesen General Drakkisath und erledigt ihn!\n\nDie Aufgabe ist sicherlich nicht einfach, aber die Belohnungen werden großartig sein.", objectives = "Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5103] = { title = "Heißer, feuriger Tod", description = "Das Einzige, was von diesem Menschen übrig geblieben ist, sind einige verkohlte Knochen. Er scheint in Armeslänge dessen gestorben zu sein, hinter dem er her war - ungebrannten Plattenstulpen.\n\nVielleicht solltet Ihr die Stulpen nehmen und aus dem Feuer verschwinden?", objectives = "Jemand auf dieser Welt muss doch wissen, was mit diesen Stulpen zu tun ist. Viel Glück!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5121] = { title = "Oberhäuptling der Winterfelle", description = "Wir wissen leider immer noch nicht, warum die Furbolgs diese merkwürdige Substanz einnehmen. Aber ich glaube, es wäre das Beste, das zu unterbinden, bevor es ausufert.\n\nDie Furbolgs der Winterfelle sind normalerweise kein aggressiver Stamm und diese Änderung ihres Verhaltens führt mich zu der Annahme, dass sie Befehle ihres Häuptlings ausführen. Wir werden wohl den Schaden, der bereits angerichtet ist, nicht mehr beheben können, aber ich denke, wenn ihr Anführer erledigt ist, wird es zumindest nicht schlimmer werden.\n\nBegebt Euch nach Osten zum Lager der Winterfelle.", objectives = "Donova Snowden in Winterspring möchte, dass Ihr den Oberhäuptling der Winterfelle besiegt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5122] = { title = "Das Medaillon des Glaubens", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5123] = { title = "Das letzte Stück", description = "Das Logbuch, das Ihr bei dem Oberhäuptling gefunden habt, scheint recht ausführlich zu sein, aber nachdem Ihr einige Seiten durchgesehen habt, stellt Ihr fest, dass Ihr den Text nicht lesen könnt. Die Zeichen sind so kunstlos und schlecht geformt, dass Ihr nicht sicher seid, ob überhaupt jemand sie lesen kann.\n\nAber vielleicht kann Donova Euch sagen, was sie bedeuten ...", objectives = "Bringt das kunstlos geschriebene Logbuch zu Donova Snowden in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5124] = { title = "Feurige Plattenstulpen", description = "Beim Barte Thaurissans!\n\nWo habt Ihr sie gefunden?\n\nNoch wichtiger: Seid Ihr bereit, Euch von ihnen zu trennen? Natürlich würde ich solch eine noble Geste belohnen.\n\nIch sag Euch was, $n. Wenn Ihr mir diese ungebrannten Stulpen gebt, werde ich Euch beibringen, wie Ihr selbst welche herstellen könnt. Ihr müsst nur die Teile für mich besorgen, damit ich das genaue Rezept benutzen kann.\n\nAbgemacht?\n\nHier ist die Liste dessen, was ich benötige. Ich werde das nicht-verzauberte Thorium selbst übernehmen, da Ihr ja die Stulpen liefert.", objectives = "Bringt Malyfous Darkhammer 6 verzauberte Thoriumbarren, 2 Essenzen des Feuers und 4 Sternrubine. Ihr müsst außerdem Eure ungebrannten Plattenstulpen abgeben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5125] = { title = "Aurius' Abrechnung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5126] = { title = "Lorax' Geschichte", description = "Der Satyr wandert auf und ab und spricht mit sich selbst. Möchtet Ihr ihn ansprechen?", objectives = "Sprecht mit Lorax. Hört, was er zu sagen hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5127] = { title = "Die Dämonenschmiede", description = "Lorax macht Geschäfte, aber er akzeptiert sie nicht von unbedeutenden Sterblichen.\n\nEinen Handel kann ich aber mit Euch machen... nehmt diese Pike, sie ist mit mächtigen Fel-Energien getränkt. Wenn Ihr Goraluk Hammerbruch findet, erschlagt ihn und treibt diese Pike durch sein sterbendes Herz. Er hat seine Seele verschachert und daher werde ich seine Seele bekommen. Bringt die Pike und die Brustplatte zurück, die der Dieb gestohlen hat, und ich werde Euch das beibringen, was er lernen sollte.", objectives = "Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.\n\nIhr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.\n\nBringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5128] = { title = "Worte des Oberhäuptlings", description = "Die Winterfelle sind für mich keine Bedrohung mehr, aber wenn Ihr immer noch herausfinden möchtet, was die Furbolgs dazu brachte, dieses merkwürdige Feuerwasser herzustellen und zu konsumieren, solltet Ihr Kelek Skykeeper aufsuchen.\n\nEr gehört zu einer Gruppe, die als Smaragdkreis bekannt ist, Druiden, die sich ihrer Arbeit im Teufelswald widmen und das Land von der Verderbnis heilen.\n\nKelek hat viel Erfahrung mit den Furbolgs im Teufelswald und kann Euch vielleicht mehr über das Logbuch sagen.\n\nNochmals danke, $N.", objectives = "Bringt das kunstlos geschriebene Logbuch zu Kelek Skykeeper im südlichen Teil des Teufelswalds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5141] = { title = "Drachenlederverarbeitung", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.", objectives = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Peter Galen in Azshara.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5142] = { title = "Klein-Pamela", description = "So viele von uns sind im Kampf von Darrowshire gefallen. So viele starben... und noch Schlimmeres.\n\nAls die Schlacht begann, versteckte ich meine Nichte Pamela, und ich weiß nicht, was mit ihr geschehen ist. Ich bin nur ein wandernder Geist, aber mein Herz möchte dennoch Pamelas Schicksal kennen.\n\nBitte, $C. Könnt Ihr nach Darrowshire gehen und nach ihr suchen? Es liegt im Osten, hinter Gahrrons Trauerfeld.", objectives = "Sucht Pamela Redpath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5143] = { title = "Stammeslederverarbeitung", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt, und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, $C: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.", objectives = "Bringt eine Wildlederweste und einen Wildlederhelm zu Caryssia Moonhunter in Feralas.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5144] = { title = "Elementarlederverarbeitung", description = "Elementarlederverarbeitung ist, was ich kann, und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, $C: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.", objectives = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Sarah Tanner in die sengende Schlucht.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5145] = { title = "Drachenlederverarbeitung", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.", objectives = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Dragoneye im Ödland.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5146] = { title = "Elementarlederverarbeitung", description = "Elementarlederverarbeitung ist, was ich kann, und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, $C: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.", objectives = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Brumn Winterhoof in den Arathi-Bergen.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5147] = { title = "GESUCHT: Arnak Grimmtotem", description = "Gesucht: Arnak Grimmtotem\n\nArnak der Ausgestoßene wird wegen ruchloser Verbrechen des Mordes und der Entführung gesucht. Ansehnliche Belohnungen winken dem, der mutig genug ist, diesen Verbrecher der Gerechtigkeit zuzuführen.\n\nArnak wurde zuletzt auf den Klippen in der Nähe des Düsterwolkengipfels gesehen. Zeigt dem Klippenbehüter Longhorn im Freiwindposten den Beweis Eurer Tat, um die Belohnung zu beanspruchen.", objectives = "Erschlagt Arnak Grimmtotem und bringt den Beweis Eurer Tat zu Klippenbehüter Longhorn im Freiwindposten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5148] = { title = "Stammeslederverarbeitung", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt, und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, $C: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.", objectives = "Bringt eine Wildlederweste und einen Wildlederhelm zu Se'Jib im Schlingendorntal.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5149] = { title = "Pamelas Puppe", description = "Meine Tante Marlene hat gesagt, ich soll in unserem Haus bleiben, weil mein Vater in den Kampf ziehen muss. Mein Vater ist der mutigste Mann auf der ganzen Welt!\n\nAber ich bin schon so lange hier und er ist nicht gekommen, um mich abzuholen. Manchmal kommen böse Leute und flüstern mir etwas zu und ich will, dass mein Vater sie wegjagt, aber er ist nicht hier!\n\nUnd manchmal, wenn es dunkel wird, möchte ich mit meiner Puppe spielen, aber das kann ich nicht, weil ich sie in der Stadt gelassen habe.\n\nKönnt Ihr vielleicht meine Puppe für mich suchen?", objectives = "Sucht Pamelas Puppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5150] = { title = "Dadanga ist hungrig!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5151] = { title = "Hyperkondensator-Dingsda", description = "Ich bin der einzige Überlebende des Angriffs der Zentauren auf unsere Karawane! Ein rarer, aber mächtiger Panther bewacht mein bestes Dingsda, das um seinen Hals geschlungen ist. Ha! Sogar die Zentauren erzittern in Anwesenheit dieser wilden Bestie!\n\nHier ist der Schlüssel zu dem Käfig. Sie haben alles dorthin gebracht, ihn aber in Ruhe gelassen. Erledigt diese Bestie, bringt meinen Hyperkondensator zurück und ich werde Euch belohnen.\n\nDie Überfallene Karawane befindet sich nördlich von hier.", objectives = "Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Bearingshiner zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5152] = { title = "Tante Marlene", description = "Oh, ich bin ja so einsam. Wo ist meine Familie? Tante Marlene hat mir gesagt, ich soll hier bleiben, aber dann ist sie weggegangen und nicht wiedergekommen! Und mein Papa... habt Ihr ihn gesehen?\n\nVielleicht weiß Tante Marlene, wo er ist. Sie lebt in der Nähe von Andorhal, in einem Haus im Süden. Ich glaub, es war auf einem Hügel... sie sagt, es wäre auf einem Hügel.\n\nBitte, $n. Wir sind doch jetzt Freunde! Könnt Ihr für mich mit meiner Tante sprechen?", objectives = "Sprecht mit Marlene, südlich der Ruinen von Andorhal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5153] = { title = "Ein seltsamer Historiker", description = "Ich wünschte, Joseph könnte wieder bei seiner Tochter sein, aber das geht nicht. Seine Seele wurde von der Geißel verdreht und er wurde zu einem Monster. Oh, er ist verloren!\n\nAber vielleicht können wir sein Schicksal ändern.\n\nDurchsucht die Gräber draußen nach Josephs Denkmal. Sein Körper ist nicht dort, da er vor Jahren zertrampelt und zerschmettert wurde, aber unter dem Denkmal liegt sein Ehering. Bringt den Ring zu Chromie ... das ist eine merkwürdige Gnomin mit sehr merkwürdigen Kräften.\n\nChromie hält sich in dem zerstörten Gasthaus im nordwestlichen Teil von Andorhal auf.", objectives = "Bringt Josephs Ehering zu Chromie.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5154] = { title = "Die Annalen von Darrowshire", description = "Um Joseph Redpath zu retten, müssen wir zuerst seine Vergangenheit enthüllen. Wir können sie den 'Annalen von Darrowshire' entnehmen, einem Buch, das im Rathaus von Andorhal aufbewahrt wird.\n\nBringt mir dieses Buch. Wir können etwas über Josephs Schicksal erfahren ... und es mit etwas Glück ... ändern!", objectives = "Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5155] = { title = "Streitmacht von Jaedenar", description = "Wenn ich Euch in dieser Angelegenheit vertrauen soll, müsst Ihr Euch zuerst als vertrauenswürdig erweisen.\n\nIch muss sicher sein, dass Ihr ein Feind des Schattenrates seid - seine Mitglieder sind für viele böse Taten nah und fern verantwortlich.\n\nReist tiefer in den Teufelswald hinein. Im Westen werdet Ihr einen Pfad sehen, der nach Jaedenar führt. Dort schmiedet der Rat Pläne zusammen mit der Brennenden Legion.\n\nBetretet die Tiefen eines der von ihnen bewohnten verderbten Grabhügel und macht sie nieder. Kehrt zu mir zurück, wenn Ihr dies erledigt habt. Dann weiß ich, dass Ihr uns wirklich helfen wollt.", objectives = "Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5156] = { title = "Die Verderbnis überprüfen", description = "Im Norden, entlang der östlichen Straße im so genannten Shatter Scar-Tal, liegt ein Bereich, wo im letzten großen Krieg Höllenbestien herbeigerufen wurden; die Krater zernarben immer noch das Land, so wie die Höllenbestien selbst.\n\nIch möchte gern zwei Dinge wissen. Erstens, durchstreifen immer noch entropische Elementare das Gebiet? Und zweitens, sind die Krater immer noch mit dem verderbten, stinkenden Wasser gefüllt, das sich dort vor Jahren gesammelt hat? Würdet Ihr das für mich überprüfen, $N? Seid aber vorsichtig, die Höllenbestien zerstören alles, was ihren Weg kreuzt.", objectives = "Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5157] = { title = "Verderbtes Wasser sammeln", description = "Tief in Jaedenar liegt die Schattenfeste - die Hauptfestung der Verderbnis und des Bösen.\n\nDer Schattenrat verfügt über Schutzzauber in Form von Kohlenpfannen, die seinen Unterschlupf umgeben. Wenn ich durch Wahrsagen noch weitere Informationen über unseren Feind herausfinden soll, müssen diese Kohlenpfannen gelöscht werden. Dann sollte ich den Rat ausspionieren und herausfinden können, wer ihn anführt.\n\nBitte, nehmt diese Feldflasche und füllt sie am Mondbrunnen im Zentrum von Jaedenar, wenn Euch dies möglich ist. Kommt dann zu mir zurück.", objectives = "Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5158] = { title = "Spirituelle Hilfe suchen", description = "Bringt das verderbte Wasser ins Brachland, $N. Südlich von Ratchet, versteckt entlang des Ufers, hält sich eine alte Freundin von mir auf, eine Schamanin namens Islen Waterseer. Sie ist eine mächtige Schamanin, die uns helfen wird. Ihre Verbindung zu den Geistern des Wassers war immer stark. Dass unsere Aufgabe edel ist, sollte ausreichen, um sie und die Geister des Wassers dazu zu bringen, bei dieser Aufgabe zu helfen.\n\nIhr dürftet sie in einem kleinen Lager direkt am Wasser finden. Ach ja, $N, ignoriert die Piraten ... sie sind nur eine Plage und keine Bedrohung für Euch.", objectives = "Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Waterseer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5159] = { title = "Gesäubertes Wasser wird zum Teufelswald gebracht", description = "Dankt den Geistern, $n. Sie sind diejenigen, die Euch zu Hilfe kamen, nicht ich.\n\nIch gebe Euch nun dieses geläuterte Wasser. Richtet Greta bitte meine Grüße und meine besten Wünsche aus. Sie kämpft mit etwas viel Größerem als die meisten von uns... wie sie sicherlich bald herausfinden wird.\n\nDer Schattenrat ist keine Kraft, die man unterschätzen sollte, $n. Vergesst das nicht.\n\nGeht jetzt. Nehmt das Wasser und kehrt zu Greta zurück.", objectives = "Bringt das geläuterte Mondbrunnenwasser zu Greta Mosshoof im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5160] = { title = "Die oberste Beschützerin", description = "Reist nach Kalimdor, $R. Unser Schwarm ist in der frostigen Landschaft von Winterspring zu Hause. Wenn Ihr Winterspring erreicht habt, sucht die Höhlen von Mazthoril.\n\nAuf den eisigen Böden von Mazthoril werdet ihr Kobaltrunen finden. Haltet eine meiner Schuppen in der Hand und stellt Euch auf eine Rune. Ihr werdet dann zu Haleh transportiert, unserer obersten Beschützerin.\n\nGebt ihr die Schuppe, damit sie weissagen kann, was ich hier an diesem verlorenen Ort gesehen und gefühlt habe.", objectives = "Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5161] = { title = "Der Zorn des blauen Drachenschwarms", description = "Wir verstehen, was die verfluchte Brut von Deathwing zu tun versucht, und wir wissen, dass das unterbunden werden muss.\n\nDurch den Schutz, den Blackrock Nefarian bietet, wird es für uns immer schwieriger zu intervenieren.\n\nWir können aber Euch, sterbliches Wesen, ermächtigen - solltet Ihr Euch dafür entscheiden.\n\nDer Weg, der vor Euch liegt, ist voller Gefahren. Ihr müsst Euch entscheiden, ob Ihr unsere Hilfe annehmt. Denkt darüber nach und sprecht erneut mit mir, wenn Ihr eine Entscheidung getroffen habt.", objectives = "Sprecht mit Haleh, wenn Ihr weitermachen wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5162] = { title = "Der Zorn des blauen Drachenschwarms", description = "Das Arkane kontrolliere ich und das Arkane wird Euch zu Eurem nächsten Ziel senden.\n\nWenn Ihr bereit seid, wird die Reise beginnen. Ihr werdet Euch zu den Pestländern begeben und mit Jeziba sprechen.\n\nEr ist ein Sterblicher, so weise wie die Uralten und so geduldig wie die unbewegliche Erde. Sucht ihn in Andorhal.", objectives = "Sprecht mit Jeziba in den Pestländern. Er wohnt in Andorhal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5163] = { title = "Sind wir endlich da, Yeti?", description = "Es ist alles bereit, $N!\n\nAlso, ich habe meinen Freunden bereits eine Nachricht geschickt und ihnen gesagt, dass ich eine Überraschung für sie habe. Und hier kommt Ihr ins Spiel!\n\nIch werde Euch meinen mechanischen Yeti geben und Ihr müsst sie überraschen, indem Ihr jeden meiner Freunde aufsucht, den Yeti einschaltet und zu ihnen schickt.\n\n Nachdem Ihr ihn Legacki in Everlook, Sprinkle in Gadgetzan und Quixxil in Marshals Zuflucht gezeigt habt, kehrt zurück und berichtet mir, was geschehen ist!\n\nBitte bringt mir meinen Yeti dann wieder zurück.", objectives = "Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit:\n\nLegacki in Everlook (Winterspring)\nSprinkle in Gadgetzan (Tanaris)\nQuixxil in Marshals Zuflucht (Un'Goro Krater)\n\nWenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5164] = { title = "Verzeichnis der Abtrünnigen", description = "Haleh hätte kein feineres Instrument der Gerechtigkeit wählen können. Lest das 'Verzeichnis der Abtrünnigen' und werdet erleuchtet.\n\nFalls Ihr durchhaltet... falls Ihr tut, was von Euch verlangt wurde... falls Ihr überlebt... werdet Ihr ein Held sein.", objectives = "Lest das 'Verzeichnis der Abtrünnigen'.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5165] = { title = "Übergießen der Flammen des Schutzes", description = "Jetzt müsst Ihr nach Jaedenar zurückkehren. Die Kohlenpfannen sind wahrscheinlich über die ganze Schattenfeste verteilt. Übergießt jede ihrer Flammen, und der Schutz, den der Rat eingerichtet hat, wird zumindest für eine kurze Zeit erlöschen. Ich werde warten, dass dies geschieht. Wenn es so weit ist, werde ich einen tiefen Blick in die Feste werfen und versuchen herauszufinden, wer der Kopf dieser Bestie ist. Dann, und nur dann, werden wir sehen, ob wir sie direkt angreifen.", objectives = "Übergießt die Flammen der vier Kohlenpfannen des Schutzes in der Schattenfeste im Teufelswald mit dem geläuterten Mondbrunnenwasser.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5166] = { title = "Brustplatte des chromatischen Drachenschwarms", description = "Das Schmieden einer mächtigen Brustplatte zum Schutz gegen die unerbittlichen Angriffe des chromatischen Drachenschwarms ist eigentlich recht ironisch.\n\nDie Schuppen der Bestien, die wir bekämpfen, müssen an einen makellosen Knochenpanzer eines alten chromatischen Drachens oder Großdrachens genäht werden. Derzeit ist nicht bekannt, ob es überhaupt welche gibt, und wir sollten hoffen, dass es niemals welche geben wird.\n\nUnd dann ist da noch die vielleicht schwierigste aller Komponenten: das Blut von Helden.\n\nDer Bildhauer muss diese Kreation dann schmieden.", objectives = "Um die Brustplatte des chromatischen Drachenschwarms zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischer Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n10 ausgefranste Monstrositätenstickereien.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5167] = { title = "Beinplatten des chromatischen Widersetzers", description = "Der Knochenpanzer eines erwachsenen chromatischen Drachen wird benötigt, um die Grundlage der Gamaschen zu fertigen. Glänzende chromatische Schuppen werden dann auf das Grundgerüst aufgebracht und im Blut der Helden verzaubert. Schließlich muss noch die geschmeidige Haut des Schattens auf die inneren Schienbeinschützer aufgebracht werden.", objectives = "Um die Beinplatten des chromatischen Widersetzers zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischer Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n5 Häute des Schattens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5168] = { title = "Helden von Darrowshire", description = "Die Helden von Darrowshire haben einen Platz in meinem Herzen und das Buch, das Ihr mir gebracht habt, die 'Annalen von Darrowshire', erzählt ihre Geschichten.\n\nEs berichtet von dem Paladin Davil Lightfire und davon, wie der Kreuzzug seinen Buchband zum Rathaus von Hearthglen brachte.\n\nEinige Passagen handeln auch von meinem Bruder, Captain Redpath. Nach seinem Verrat wurde sein Schild zerschmettert und weggeworfen und liegt nun am unwahrscheinlichsten aller Orte - in der Nähe von Gahrrons Trauerfeld.\n\nSammelt diese Relikte, $N. Denn Verhängnis und Tragik umgeben sie.", objectives = "Bringt Davils Buchband und Redpaths Schild zu Carlin Redpath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5181] = { title = "Bösewichte von Darrowshire", description = "Die 'Annalen von Darrowshire' berichten von den Bösewichten dieser Schlacht. Sie berichten, wie der Ghullord Horgus der Verheerer von Kräften der Allianz während der Schlacht vernichtet wurde. Seine Leiche wurde in einen See geworfen, nordwestlich von Corins Kreuzung, und sein Schädel ist noch dort.\n\nMarduk der Schwarze wurde nie besiegt, aber sein sagenhaftes Schwert wurde zertrümmert und ging verloren. Es liegt auf dem Grund der Schlucht westlich von Corins Kreuzung.\n\nBringt diese Gegenstände zurück, $N. Ich weiß nicht, warum, aber ich bin sicher, dass ihr Schicksal in Euren Händen liegt.", objectives = "Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Redpath in der Kapelle des hoffnungsvollen Lichts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5201] = { title = "Eindringlinge der Winterfelle", description = "Meine Anwesenheit bleibt den Meisten verborgen, $N. Es gibt aber eine Störung, die hier in Winterspring fest verankert zu sein scheint: die Winterfellfurbolgs.\n\nObwohl ich die Furbolgs nie direkt angegriffen habe, scheinen sie wahnsinnig zu sein, alles, was in ihrem Weg steht, scheint sie zu ängstigen. Ich habe beobachtet, wie sie zahllose Kreaturen erschlagen haben, die das Pech hatten, einfach zur falschen Zeit am falschen Ort zu sein.\n\nIch bin ihrer Einmischungen müde ... helft mir bitte, indem Ihr sie bekämpft. Erschlagt die Furbolgs und haltet sie vom Frostsäblerfelsen fern.", objectives = "Rivern Frostwind möchte, dass Ihr 5 Schamanen der Winterfelle und 5 Ursa der Winterfelle erschlagt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5202] = { title = "Ein merkwürdiger roter Schlüssel", description = "Der kleine rote Schlüssel scheint aus einem Knochenmaterial gemacht zu sein. Er liegt schwer in Eurer Hand, wirkt aber trotzdem sehr zerbrechlich. Warum sollte ein Mitglied des Schattenrats solch ein Ding haben? Vielleicht gibt es etwas in Jaedenar, was dieser merkwürdige Schlüssel aufschließen kann.", objectives = "Durchsucht Jaedenar, um herauszufinden, wofür der blutrote Schlüssel verwendet wird.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5203] = { title = "Rettung aus Jaedenar", description = "Aber so sehr es mich auch schmerzt, es gibt eine Sache, die zuerst erledigt werden muss. Ich muss Treys Schwert Lightforge finden und aus der Schattenfeste entkommen, um meinen Vorgesetzten zu berichten, was hier geschieht. Könntet Ihr mir helfen, $N?\n\nUnsere Ausrüstung ist nicht weit von hier und Ihr habt bereits bewiesen, dass Ihr den Weg an die Spitze überleben könnt.\n\nNachdem wir entkommen sind, werde ich nach Darnassus gehen, und Euch würde ich bitten, meine Freundin Jessir in der Nähe der Grenze zu Ashenvale aufzusuchen. Sie sollte sich eigentlich im Lager des Smaragdkreises hier in der Nähe mit uns treffen.\n\nWas sagt Ihr dazu, $N? Würdet Ihr mir nochmals helfen?", objectives = "Bringt Arko'narin dorthin, wo Lightforge und ihre Ausrüstung aufbewahrt werden, und beschützt sie dann bei eurer Flucht aus der Schattenfeste. Sucht danach Jessir Moonbow im Teufelswald auf und lasst sie wissen, was mit ihren Freunden geschehen ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5204] = { title = "Vergeltung des Lichts", description = "Sie möchte so tun, als ob es ihr gut ginge. Sie möchte gern, dass ich denke, sie sei stark genug, um mit alledem selbst fertig zu werden, aber ich weiß es besser. Treys Tod und zu hören, welche Folter er erdulden musste, wird sie lange Zeit verfolgen, und es gibt nichts, was wir tun können, um das zu stoppen. Aber wir können ihr ein wenig Frieden geben!\n\n$N, kehrt zur Schattenfeste zurück, tötet Treys Folterknecht und sucht seine Überreste. Es gibt keinen Grund, dass wir nicht all diese Dinge zu Ende bringen können, während Arko'narin auf ihre eigene Art trauert.", objectives = "Kehrt nach Jaedenar zurück und tötet den Sukkubus Rakaiah, bevor Ihr die Überreste von Trey Lightforge sucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5206] = { title = "Marodeure von Darrowshire", description = "Chromie sagte, dass die von Euch gesammelten Relikte Reagenzien für einen mächtigen Zauber seien und dass noch eines fehle: Schädel von Angehörigen der Geißel, die an der Schlacht von Darrowshire teilnahmen.\n\nNehmt diesen Kristall und jagt um ihrer Schädel willen Champions der Geißel. Der Kristall ist verzaubert: Wenn ein Held an der Schlacht teilnahm, dann wird er, wenn Ihr ihn über dessen Schädel haltet, widerhallen. Bringt mir diese widerhallenden Schädel.\n\nGeht, $N. Ihr könnt Champions der Geißel im giftigen Tal im Norden und im Fungustal im Westen finden.", objectives = "Bringt 5 widerhallende Schädel und den mystischen Kristall zu Carlin Redpath in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5210] = { title = "Bruder Carlin", description = "Die 'Annalen von Darrowshire' haben mit Hilfe meiner Magie an ihrem Ende Seiten hinzugewonnen, und nun erstreckt sich die Geschichte auch über den Kampf hinaus. Eine der zusätzlichen Passagen berichtet von einem anderen Redpath, Carlin, der Josephs Verrat überlebt hat. Carlin befindet sich jetzt in den Pestländern im Osten, bei der Kapelle des hoffnungsvollen Lichts.\n\nNehmt das Buch und sprecht mit ihm.", objectives = "Bringt die erweiterten 'Annalen von Darrowshire' zu Carlin Redpath in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5211] = { title = "Verteidiger von Darrowshire", description = "Viele der Verteidiger fielen in der Schlacht von Darrowshire. Und viele ziehen erneut umher als grässliche Diener der Geißel! Sucht diese armen Seelen und beendet ihr Elend!\n\nJagt Menschenfresserghuls, plappernde Ghuls und kranke Schinder. Viele dieser Satanskreaturen waren einst gute Leute aus Darrowshire und die Zerstörung ihrer Formen wird ihre Seelen befreien.\n\nIhr werdet sie im Pestwald und bei Corins Kreuzung finden, ebenso wie in anderen Geißelfestungen in den östlichen Pestländern.", objectives = "Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5212] = { title = "Das Fleisch lügt nicht", description = "Die Apotheker der Verlassenen sind nicht die einzigen Wesen auf dieser Welt, die in den Wissenschaften bewandert sind.\n\nIch erforsche die Seuche schon seit Jahren, $R. Wir dachten zuerst, dass die Stärke der Seuche langsam schwand, aber was ich hier in den Pestländern entdeckt habe, ist alarmierend. Die Kraft der Seuche scheint zu wachsen!\n\nIch muss mehr Tests durchführen! Die mächtigste Quelle der Seuche ist das besudelte Fleisch der vor Kurzem Infizierten. Begebt Euch nach Stratholme und bringt mir Proben, $n.", objectives = "Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5213] = { title = "Der aktive Wirkstoff", description = "Ihr müsst tiefer nach Stratholme vordringen, $n.\n\nHinter den ersten Toren werdet Ihr die Ziggurats finden. Wir wissen, dass die Geißel große Macht aus diesen Gebäuden zieht. Durchsucht die Ziggurats und kehrt mit den Informationen zurück, die Ihr aufspürt.", objectives = "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5214] = { title = "Der große Fras Siabi", description = "Schrecklich... was mit Fras geschehen ist. Wisst Ihr, die Stadt wurde geplündert und Fras wollte seine wertvollen Dinge nicht zurücklassen. Das Letzte, woran ich mich erinnere, ist, dass er sagte: 'Ich werde jede einzelne Seite verbrennen, bevor ich zulasse, dass sie sie in ihre verdammten, schmutzigen Pfoten kriegen!'\n\nIch rauche ja auch ganz gern mal eine Zigarre, aber ich bin kein Idiot. Ich habe Fras und sein reizendes Geschäft an dem Tag verlassen. Ich nehme an, dass er in den Flammen unterging, aber wenn es eine Chance gibt, dass auch nur ein Kasten seines berühmten Tabaks noch intakt ist...\n\nWas sagt Ihr dazu, $n? Sucht Ihr einen Kasten für den alten Smokey?", objectives = "Sucht Fras Siabis Raucherladen in Stratholme und bergt einen Kasten von Siabis Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5215] = { title = "Die Geißelkessel", description = "In den Ländern des ehemaligen Lordaeron befinden sich acht Kessel - vier hier im Westen und vier weitere versteckt im Osten. Diese Kessel speien Gifte in die Luft und verbreiten die Seuche für die Geißel im ganzen Land.\n\nDie nekromantische Macht von Kel'Thuzad ist zu stark, um diese Kessel gänzlich zu schließen, aber wir glauben zu wissen, wie wir sie zu unserem Vorteil nutzen könnten. Meine rechte Hand, die Hohepriesterin MacDonnell, wird Eure Kontaktperson für diesen Auftrag sein; sie wird die Einweisung fortsetzen.", objectives = "Sprecht mit der Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5216] = { title = "Ziel: Teufelssteinfeld", description = "Von den vier Kesseln, die sich hier im Westen befinden, ist derjenige, der sich auf dem Teufelssteinfeld befindet, wohl der, zu dem der Zugang am einfachsten ist. Die Geißel hat hier Truppen mit weniger Erfahrung positioniert, sie sollten aber trotzdem nicht unterschätzt werden.\n\nGeht zum Teufelssteinfeld, nordwestlich von Andorhal, und befasst Euch dort mit dem Kessellord. Wir glauben, dass er einen Schlüssel hat, der den Zugang zu dem Kessel freigeben wird. Wenn er frei ist, benutzt diese Flasche, um dem Kessel eine Probe des Giftes zu entnehmen; wir benötigen sie für die Entwicklung eines Gegenwirkstoffs.", objectives = "Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5217] = { title = "Rückkehr zum Chillwind-Lager", description = "Ihr füllt die Flasche mit einer ausreichenden Menge des giftiges Gebräus aus dem Kessel, sodass es für eine Probe zur Untersuchung reicht.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Chillwindspitze zurückzukehren, um die Mission abzuschließen.", objectives = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5218] = { title = "Der Kessel des Teufelssteinfelds", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5219] = { title = "Ziel: Dalsons Tränenfeld", description = "Einer der Seuchenkessel befindet sich auf dem Feld eines ehemaligen Bauernhauses, das jetzt Dalsons Tränenfeld genannt wird. Tja, wir werden heute keine Tränen vergießen, wenn wir der Geißel in die Quere kommen und sie an ihren eigenen Dämpfen ersticken lassen!\n\nBegebt Euch zu Dalsons Tränenfeld, ziemlich genau nördlich von Andorhal, und eliminiert den Kessellord dort. Er sollte, wie der Letzte auch, einen Schlüssel haben, durch den Ihr an den Kessel gelangen könnt. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen; jeder Kessel enthält ein jeweils für ihn einzigartiges Gebräu aus Toxinen, das nur er benutzt.", objectives = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5220] = { title = "Rückkehr zum Chillwind-Lager", description = "Vorsichtig füllt Ihr so viel, wie Ihr für eine sinnvolle Probe für nötig erachtet, von dem Sekret aus dem Kessel in die Flasche.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Chillwindspitze zurückzukehren, um die Mission abzuschließen.", objectives = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5221] = { title = "Der Kessel von Dalsons Tränenfeld", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5222] = { title = "Ziel: Das Trostlose Feld", description = "Zwei Kessel wurden erfolgreich geöffnet. Auf diese könnt Ihr jetzt zwar unbegrenzt zugreifen, aber wir möchten immer noch, dass Ihr die beiden verbleibenden öffnet. Damit erhielten wir weitere Möglichkeiten, den Gegenwirkstoff einzusetzen!\n\nDieses Mal werdet Ihr Euch um den Kessel des Trostlosen Felds kümmern. Er befindet sich ziemlich genau östlich von Andorhal, relativ nahe bei den zerstörten Stadtmauern. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen.\n\nGute Jagd, $n!", objectives = "Begebt Euch zum Trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das Trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5223] = { title = "Rückkehr zum Chillwind-Lager", description = "Vorsichtig füllt Ihr die leere Flasche. Jetzt schwappt eine Probe der stinkenden Substanz, die unter der Plattform des Kessels brodelt, in dem zerbrechlichen Glasbehälter herum.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Chillwindspitze zurückzukehren, um die Mission abzuschließen.", objectives = "Bringt die gefüllte Flasche: Das trostlose Feld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5224] = { title = "Der Kessel des Trostlosen Felds", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5225] = { title = "Ziel: Gahrrons Trauerfeld", description = "Der letzte verbleibende Kessel befindet sich auf einem Hof, der jetzt Gahrrons Trauerfeld genannt wird. Er wird durch einige der stärkeren Diener der Geißel bewacht... um genau zu sein durch Gespenster und Geisterscheinungen. Die darf man nicht unterschätzen, $n.\n\nGahrrons Trauerfeld liegt von unserer Position hier aus im Nordosten, etwa dort, wo die Östlichen Pestländer beginnen. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Hier ist Eure leere Probenflasche; bringt sie mir gefüllt zurück. Möge das Licht Euch bei dieser gefährlichen Mission schützen, $C.", objectives = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5226] = { title = "Rückkehr zum Chillwind-Lager", description = "Ihr schließt sorgfältig den Hahn in der Zugangsklappe und beobachtet, wie das faulige Sekret des Kessels in die leere Flasche tropft.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Chillwindspitze zurückzukehren, um die Mission abzuschließen.", objectives = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
