quests[5228] = { title = "Die Geißelkessel", description = "In den Ländern des ehemaligen Lordaeron befinden sich acht Kessel - vier im Westen und vier weitere verschanzt im Osten. Diese Kessel speien Gifte in die Luft und verbreiten die Seuche für die Geißel im ganzen Land.\n\nDie nekromantische Macht von Kel'Thuzad ist zu stark, um diese Kessel gänzlich zu schließen, aber wir glauben zu wissen, wie wir sie zu unserem Vorteil nutzen könnten. Meine rechte Hand, die Schattenpriesterin Vandis wird Eure Kontaktperson für diesen Auftrag sein; sie wird die Einweisung fortsetzen.", objectives = "Sprecht mit der Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5229] = { title = "Ziel: Teufelssteinfeld", description = "Von den vier Kesseln, die sich in den Westlichen Pestländern befinden, ist derjenige, der sich im Teufelssteinfeld befindet, wohl der, zu dem der Zugang am einfachsten ist. Die Geißel hat hier Truppen mit weniger Erfahrung positioniert, sie sollten aber trotzdem nicht unterschätzt werden.\n\nGeht zum Teufelssteinfeld, direkt östlich von hier und nordwestlich von Andorhal, und befasst Euch dort mit dem Kessellord. Er hat einen Schlüssel bei sich, der den Zugang zu dem Kessel freigeben wird. Wenn er frei ist, benutzt diese Flasche, um dem Kessel eine Probe des Giftes zu entnehmen; wir benötigen sie für die Entwicklung eines Gegenwirkstoffs.", objectives = "Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5230] = { title = "Rückkehr zum Bollwerk", description = "Ihr füllt die Flasche mit einer ausreichenden Menge des giftiges Gebräus aus dem Kessel, sodass es für eine Probe zur Untersuchung reicht.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", objectives = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5231] = { title = "Ziel: Dalsons Tränenfeld", description = "Einer der Seuchenkessel befindet sich auf dem Feld eines ehemaligen Bauernhauses, das jetzt Dalsons Tränenfeld genannt wird. Heute werden keine Tränen vergossen, $C; wir müssen bei diesem Kessel zuschlagen und Zugang zu ihm erlangen!\n\nBegebt Euch zu Dalsons Tränenfeld, fast direkt nördlich von Andorhal, und eliminiert den Kessellord dort. Er sollte, wie der Letzte auch, einen Schlüssel haben, durch den Ihr ans Innere des Kessels gelangen könnt. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen; jeder Kessel enthält ein jeweils für ihn einzigartiges Gebräu aus Toxinen, das nur er benutzt.", objectives = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5232] = { title = "Rückkehr zum Bollwerk", description = "Vorsichtig füllt Ihr so viel, wie Ihr für eine sinnvolle Probe für nötig erachtet, von dem Sekret aus dem Kessel in die Flasche.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", objectives = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5233] = { title = "Ziel: Das Trostlose Feld", description = "Zwei Kessel wurden erfolgreich geöffnet. Auf diese könnt Ihr jetzt zwar unbegrenzt zugreifen, aber wir möchten immer noch, dass Ihr die beiden verbleibenden öffnet. Damit erhielten wir weitere Möglichkeiten, den Gegenwirkstoff einzusetzen!\n\nDieses Mal werdet Ihr Euch um den Kessel des Trostlosen Felds kümmern. Er befindet sich ziemlich genau östlich von Andorhal, relativ nahe bei den zerstörten Stadtmauern. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen.\n\nGute Jagd, $n!", objectives = "Begebt Euch zum Trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das Trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
