quests[5235] = { title = "Ziel: Gahrrons Trauerfeld", description = "Der letzte verbleibende Kessel befindet sich auf einem Hof, der jetzt Gahrrons Trauerfeld genannt wird. Er wird durch einige der stärkeren Diener der Geißel bewacht... um genau zu sein durch Gespenster und Geisterscheinungen. Die darf man nicht unterschätzen, $n.\n\nGahrrons Trauerfeld liegt weit im Osten vom Bollwerk aus gesehen, etwa dort, wo die Östlichen Pestländer beginnen. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Hier ist Eure leere Probenflasche; bringt sie mir gefüllt zurück. Mögen die Schatten Euch für diese gefährliche Mission in Sicherheit hüllen, $C.", objectives = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5236] = { title = "Rückkehr zum Bollwerk", description = "Ihr schließt sorgfältig den Hahn in der Zugangsklappe und beobachtet, wie das faulige Sekret des Kessels in die leere Flasche tropft.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", objectives = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5237] = { title = "Mission erfüllt!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5238] = { title = "Mission erfüllt!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5241] = { title = "Onkel Carlin", description = "Manchmal kann ich nachts meinen Onkel Carlin weinen hören. Es klingt, als ob er weit weg wäre, im Osten.\n\nIch hoffe, dass er nicht um mich weint! $n, werdet Ihr meinen Onkel suchen und ihm sagen, dass es mir gut geht?\n\nWenn Ihr ihn findet, sagt ihm, dass ich auf ihn warte und die Geschichte hören möchte, die er immer erzählt hat... die über die Hasen und die Marmelade! Die Geschichte ist so lustig!", objectives = "Sucht Carlin Redpath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5242] = { title = "Der endgültige Schlag", description = "Leider scheint die einzige Möglichkeit, diese Bedrohung für den Teufelswald zu stoppen, ein Frontalangriff zu sein. Es gibt keine anderen Wege in die Schattenfeste und ich habe keine Möglichkeit, Euch ins Innere zu teleportieren. Der gerade Weg hinab in die Tiefe ist der einzige Weg... und ich weiß auch, wen Ihr aufsuchen solltet. Sein Name ist Fel'dan ... Schattenlord Fel'dan. Er ist der Sterbliche, der dort unten die Macht hat... er ist der Kopf der Schlange. Tötet ihn und seine beiden Sukkubus-Diener und kehrt zu mir zurück. Fel'dan ist derjenige, der Pakte mit der Legion schließt. Er muss aufgehalten werden.", objectives = "Tötet Moora und Salia und bringt den Kopf von Schattenlord Fel'dan zu Greta Mosshoof im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5243] = { title = "Häuser der Heiligen", description = "Ich sehe meinen Untod als eine Krankheit an, $R. Eine Krankheit, die einfach nur eine Behandlung erfordert; sie ist aber auch ein großer Segen für die Argentumdämmerung. Wie kann man die Heiden der Geißel besser schlagen als durch den Untod?\n\nIch werde von meinen Kollegen wegen der Opfer, die ich dargebracht habe, geachtet, aber das Lob bedeutet mir nichts.\n\nWenn Ihr daran interessiert seid, der Argentumdämmerung zu helfen, kann ich Euch einen Auftrag anbieten.\n\nBegebt Euch nach Stratholme und holt unsere Reserven an heiligem Wasser. Durchsucht die Vorratskisten.", objectives = "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5244] = { title = "Die Ruinen von Kel'Theril", description = "Die Geschichte hinter Kel'Theril ist die eines verfluchten Volkes, gebunden an den Ort, an dem es ein unglückliches Ritual versuchte...\n\nDie Hochgeborenen, die Ihr dort finden werdet, stahlen einst ein hochheiliges Artefakt in dem Glauben, dass sie seine Macht für sich selbst nutzen und so noch mächtiger werden könnten. Durch ihre Bemühungen zerbrach das Relikt in einer gewaltigen Explosion, bei der die Teile unter das Eis des Sees getrieben wurden...\n\nSprecht mit Jaron Stoneshaper, wenn Ihr mehr erfahren möchtet; er hat das Gebiet vor kurzem besucht und kann Euch mehr berichten.", objectives = "Sprecht mit Jaron Stoneshaper in Starfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5245] = { title = "Die gequälten Seelen von Kel'Theril", description = "Die Geister der Hochgeborenen sind erbärmliche Kreaturen, das ist mal sicher. Sie suchen immer noch nach Teilen dessen, was sie für immer nach Kel'Theril verdammte - das gestohlene Relikt.\n\nWenn Ihr so daran interessiert seid, nehmt meine Hacke und geht nach Süden zum See. Seht, ob Ihr die Teile des Relikts aus dem Eis holen könnt.\n\nWas Ihr da finden werdet, darüber kann ich Euch nichts sagen, aber ich kenne jemanden, der es vielleicht kann... Aurora Skycaller; sie lebt beim Nordpassturm im nördlichen Teil der Östlichen Pestländer.", objectives = "Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5246] = { title = "Fragmente der Vergangenheit", description = "Ich wusste nicht, dass... Vergebt mir meine harten Worte, $C.\n\nÜber die Fehler meiner Vorfahren möchte ich mich nicht auslassen, aber wenn Eure Bitte wirklich echt ist, dann werde ich Euch helfen.\n\n<Aurora untersucht die Fragmente.>\n\nIch glaube, dass dies der Kristall von Zin-Malor ist, ein Artefakt, das starke arkane Kräfte fesseln und kontrollieren kann. Es hätte für das Gute genutzt werden können, aber die bösen Absichten derjenigen, die es stahlen, ließen es zersplittern.\n\nBegebt Euch zum Tempel von Zin-Malor in Azshara - ich kann nur hoffen, dass das Buch noch dort ist.", objectives = "Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5247] = { title = "Fragmente der Vergangenheit", description = "Ich kann Euch helfen, wenn Ihr das Artefakt wirklich wiederherstellen wollt.\n\nUm die Teile wieder zusammenzufügen und zu versiegeln, werde ich Gegenstände mit starken magischen Eigenschaften benötigen. Einen verzauberten Thoriumbarren und fünf Kristallflicker ... Ihr werdet außerdem etwas Wasser von einem seltsam anmutenden Ort holen müssen ... Sucht den Düsterteich entlang der Eldrethgasse in Düsterbruch in Feralas auf und füllt dort diese Phiole.\n\nWährend Ihr unterwegs seid, werde ich versuchen, diesen Seiten das Wissen zu entnehmen, das ich benötige, um den Schaden zu reparieren, der an dem Relikt verursacht wurde.", objectives = "Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5248] = { title = "Gequält von der Vergangenheit", description = "$N, ich weine ob dessen, was in der Vergangenheit geschehen ist. Wie dieser Kristall wurden auch die Elfen als Volk zerschmettert. Ich weiß nicht, ob die Teile jemals wieder zu einem vereinigt werden können, aber meine Trauer wurde dadurch gelindert, dass ich Euch bei dieser kleinen Aufgabe helfen konnte. \n\nWir dürfen die Vergangenheit nicht vergessen, $N ...\n\nBringt bitte den Kristall von Zin-Malor zurück zum Kel'Therilsee. Ihr müsst einen Geist eines Hochgeborenen finden, der erkennt, was für ein Fehler vor so langer Zeit begangen wurde. Zeigt dem Geist, dass wir die Dinge wieder in Ordnung gebracht haben.", objectives = "Bringt den Kristall von Zin-Malor zum Kel'Therilsee in Winterspring und sucht einen Geist eines Hochgeborenen, der mit Euch sprechen will.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5249] = { title = "Nach Winterspring!", description = "In Winterspring, nördlich von hier, gibt es viele alte Elfenruinen. Es ist ein raues Land, aber man kann dort viele Geheimnisse und Orte erkunden.\n\nBei der vielen Arbeit, die hier im Teufelswald meiner harrt, hatte ich keine Gelegenheit, nach Winterspring zu reisen. Aber es gibt keinen Grund, warum Ihr es nicht tun solltet!\n\nWährend Ihr dort seid, sucht doch nach Wynd Nightchaser. Er verbringt den Großteil seiner Zeit in Starfall und er weiß viel über die Gegend.", objectives = "Sucht Starfall in Winterspring und sprecht mit Wynd Nightchaser.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5250] = { title = "Sternfall", description = "In Winterspring, nördlich des Teufelswaldes, gibt es viele alte Elfenruinen. Es ist ein raues Land, aber man kann dort viele Geheimnisse und Orte erkunden.\n\nMeine Studien hier beschäftigen mich so sehr, dass ich seit einiger Zeit keine Gelegenheit mehr hatte, nach Winterspring zu reisen. Aber es gibt keinen Grund, warum Ihr nicht dorthin reisen und die Ruinen erforschen solltet.\n\nWährend Ihr dort seid, sucht doch nach Wynd Nightchaser. Er verbringt den Großteil seiner Zeit in Starfall und er weiß viel über die Gegend.\n\nSagt ihm, dass Ihr einer meiner Schüler seid ...", objectives = "Sucht Starfall in Winterspring und sprecht mit Wynd Nightchaser.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5251] = { title = "Der Archivar", description = "Alles, was zum Extremen getrieben wird, ist für unsere Welt gefährlich, $n. Nehmt zum Beispiel den Scharlachroten Kreuzzug. Glaubt Ihr, dass der blinde Fanatismus seiner Anhänger etwas Gutem dient? Wie viele Unschuldige haben sie im Namen des Lichts vernichtet?\n\nGotteslästerer, alle zusammen!\n\nEiner interessiert mich aber besonders, der Archivar Galford von Stratholme: ein Mann, der über die wertvollsten Dokumente des Kreuzzugs wacht. Vernichtet ihn und verbrennt seine Archive! Wenn Ihr erfolgreich seid, kehrt zu mir zurück und Ihr werdet belohnt.", objectives = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5252] = { title = "Reuevolle Hochgeborene", description = "Der... der Kristall...\n\nDie Hochgeborenen hier sssind durch ihr eigenessss Elend verwirrrrt...\n\nIch bin betrrrrübt, aber ich erkenne den Fehlerrr dessen, wassss vor so langer Zeit geschah. Obwohl esss keine Möglichkeit giiibt, die Vergangenheit zu ändern, habe ich nun Friiiieden gefunnnnden, da ich weiß, dass Ihr den Kristall von Zin-Malor wiederbeschafft habt...\n\nIiihr müsssssst ihn zurückbringennnn...\n\nEr muuussss zurückgebracht werrrdennnn.", objectives = "Sprecht mit Wynd Nightchaser in Starfall und fragt nach dem richtigen Ort für den Kristall von Zin-Malor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5253] = { title = "Der Kristall von Zin-Malor", description = "Recht eindrucksvoll, $N.\n\nDer Kristall von Zin-Malor kann niemals in den Tempel zurückgebracht werden, der, wie Ihr wisst, nur noch eine Ruine ist. Aber ich finde, dass Eure Bemühung, das Böse der Vergangenheit ungeschehen zu machen, nicht ohne Belohnung bleiben soll.\n\nSucht den Erzdruiden Fandral Staghelm in Darnassus auf und bringt ihm den Kristall, $N. Er sollte sich in den Händen derer befinden, die seine Macht nicht missbrauchen werden. Wie es aussieht, sind von den stärksten Magieanwendern nur eine Hand voll in der Lage, solch eine Macht zu kontrollieren.", objectives = "Überbringt dem Erzdruiden Fandral Staghelm in Darnassus den Kristall von Zin-Malor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5261] = { title = "Eagan Pelzschneider", description = "Eagan Peltskinner sucht nach jemandem, der für ihn Wölfe jagt. Das ist gut, da wir es hier im Nordhaintal in letzter Zeit verstärkt mit Wölfen zu tun haben.\n\nWenn Ihr interessiert seid, dann sprecht mit Eagan. Ihr findet ihn neben der Abtei, auf der linken Seite.", objectives = "Sprecht mit Eagan Peltskinner.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5262] = { title = "Die Wahrheit zeigt sich mit Macht", description = "Ihr versucht, Eure Gedanken zu sammeln, während sich der Staub in der Kammer wieder setzt. Ihr geht in Gedanken die Ereignisse durch, die sich gerade ereignet haben, und könnt dennoch die Schwere der Situation nicht verstehen.\n\nDer oberste Kreuzzügler des Scharlachroten Kreuzzugs ein Dämon? Und nicht nur irgendein Dämon, sondern der Bruder von Varimathras, Erzlord von Undercity?\n\nIhr verstaut den abgetrennten Kopf des Schreckenslords sorgfältig in Eurem Rucksack. Natürlich würde Euch niemand diese Geschichte ohne Beweise glauben.\n\nFürst Nicholas Zverenhoff muss sofort davon erfahren!", objectives = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5263] = { title = "Übertroffen", description = "Ihr zeigt eine natürliche Begabung für die Kunst der Zerstörung und Ihr folgt Befehlen. Es ist selten, dass beides zusammentrifft. In mir keimt immer mehr der Gedanke, dass Ihr ein hervorragendes Mittel göttlicher Gerechtigkeit darstellen könntet.\n\n<Zverenhoff verschränkt seine Hände vor seinem Gesicht.>\n\nDer Laufbursche von Kel'Thuzad regiert über Stratholme. Beweist mir, dass Ihr ein Held seid - mein Held. Vernichtet Baron Rivendare und kehrt mit seinem Kopf zu mir zurück.", objectives = "Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5264] = { title = "Lord Maxwell Tyrosus", description = "Ich werde Euch eine große Ehre zuteil werden lassen, $N.\n\nLord Maxwell wünscht, Euch für Euren Dienst an der Argentumdämmerung zu belohnen!\n\nEs ist Jahre her, seitdem Maxwell das letzte Mal einem Außenstehenden eine Audienz gewährt hat.", objectives = "Sprecht mit Lord Maxwell Tyrosus. Er befindet sich in der Kirche.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5265] = { title = "Der Argentumtresor", description = "Über viele Jahre hinweg blieb der Argentumtresor verschlossen. Niemand war würdig genug, hineinzugreifen und die Macht der Argentumdämmerung herauszunehmen - bis heute.\n\nDer Argentumtresor ist nun für Euch geöffnet, $n.", objectives = "Öffnet den Argentumtresor und nehmt Euch Eure Belohnung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5281] = { title = "Die ruhelosen Seelen", description = "Da gibt es diejenigen, die tragisch beim Fall von Stratholme starben. Viele nahmen sich das Leben, entschieden sich dafür, sich lieber selbst in die Myriaden Flammen der glimmenden Stadt zu stürzen, statt einer der Geißel zu werden.\n\nNun ziehen sie als ruhelose Geister durch die Straßen von Stratholme.\n\nWir müssen ihnen helfen, $n!\n\nIch habe einen Partner namens Egan, der wunderbare Arbeit mit Geistern und Seelen geleistet hat. Sucht ihn auf. Er streift durch die Östlichen Pestländer, in der Nähe von Stratholme, und testet seine Neuheiten.", objectives = "Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5282] = { title = "Die ruhelosen Seelen", description = "Ich ziehe meine Macht - meinen Willen, weiter zu leben und zu atmen - aus dem ganzen Hass, den ich der Geißel entgegenbringe, und allem, was sie getan hat. Ich bin aber trotzdem kein Eiferer. Es gibt die, wie die Mitglieder des Scharlachroten Kreuzzugs, die die unschuldigen Untoten eher vernichten würden, als ihnen auch nur ein wenig Mitleid entgegenzubringen.\n\nDas bringt mich zu dem hier: meinem Blaster. Er wird die gequälten Seelen von Stratholme erlösen.\n\nWendet ihn auf die Geisterscheinungen an, die die geplünderten Straßen durchstreifen. Befreit ihre Seelen.", objectives = "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!\n\nBefreit 15 ruhelose Seelen und kehrt zu Egan zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5283] = { title = "Die Kunst des Rüstungsschmiedes", description = "Tja, Ihr habt 'ne kluge Entscheidung getroffen.\n\nWir haben nix füreinander übrig, ich und der alte Ironus hier. Dieser nichtsnutzige Spielzeughersteller weiß, wer die wahren Handwerker hier sind.\n\nDie wirklich großen Kriege werden mit 'ner guten Verteidigung gewonnen. Wenn's losgeht, wird Euch kein Angriff helfen.\n\nAlso dann, ran an die Arbeit! Ihr müsst mir nur zeigen, dass Ihr über Talent verfügt. Danach reiß ich alle Unreinheiten, die noch in Euch sind, raus und mach einen Rüstungsschmied aus Euch. Ihr wisst doch, wie man verschnörkeltes Mithril herstellt, nicht wahr?", objectives = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Grumnus bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5284] = { title = "Der Weg des Waffenschmieds...", description = "Als Waffenschmied werdet Ihr feststellen, dass sehr häufig Helden und Abenteurer der Ausrüstung wegen zu Euch kommen werden. Wenn die viele Arbeit manchmal auch unerträglich sein kann, macht der Wohlstand aber doch die Rückenschmerzen und die Aschenlunge wett.\n\nOh ja, $n, Waffenschmiede sind die mit dem ganzen Gold!\n\nWenn Ihr unseren Rängen beitreten wollt, müsst Ihr mir zeigen, dass Ihr mir ein Silberstück oder zwei machen könnt - ich meine, zeigt mir, dass Ihr habt, was man braucht, wenn Menschen Waffen überragender Qualität benötigen. An die Arbeit!", objectives = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Ironus bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5301] = { title = "Die Kunst des Rüstungsschmiedes", description = "Zufriedenheit. Das bekomme ich von Hammer und Amboss. Einen stolzen Krieger der Horde zu sehen, der von meinem Stahl geschützt ist, erinnert mich daran, was es heißt, am Leben zu sein. Das ist eine Sucht, die ich niemals ablegen werde, $n.\n\nIch kann Euch diese Zufriedenheit nicht garantieren, Euch nur auf den Weg dazu bringen. Wie bei allen Bestrebungen des Lebens ist auch der Weg des Rüstungsschmieds eine Reise.\n\nWenn Ihr einer der wenigen Erwählten sein wollt, müsst Ihr nur fragen und ich werde Euch ausbilden, aber zuerst müsst Ihr eine Aufgabe erledigen.", objectives = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Okothos bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5302] = { title = "Der Weg des Waffenschmieds...", description = "Eines Tages werde ich einen legendären Hammer erschaffen. Einen Hammer, der eines Kriegshäuptlings würdig ist!\n\nDas ist mein Lebenswerk, $N. Meine Leidenschaft. Ich erkenne, dass Ihr das Potenzial habt, zu uns zu gehören, einer von uns zu sein - ein Waffenschmied. Ich bin derjenige, der Euch helfen kann, dieses Potenzial nutzbar zu machen.\n\n Alles, was Ihr dafür erledigen müsst, ist eine einfache Aufgabe. Einfach für jemanden von Eurer außergewöhnlichen Fertigkeit.", objectives = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Borgosh bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5305] = { title = "Süße Beschaulichkeit", description = "In den Grenzen der scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch zu einem Hammerschmied ausbilden.\n\nIhr müsst eines wissen: Wenn Ihr Euch für den Weg des Hammerschmieds entschieden habt, sind die Wege des Schwertschmieds und des Axtschmieds nicht mehr verfügbar.", objectives = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5306] = { title = "Schlangenstein der Schattenjägerin", description = "Lasst Euch von ihrer Schönheit nicht narren, $C. Die Schattenjägerin Vosh'gajin ist todbringend und wahnsinnig.\n\n<Kilram zeigt auf die Narbe in seinem Gesicht.>\n\nJa, die habe ich von ihr - eine Liebkosung, wie sie es nannte.\n\nJetzt endlich ist die Zeit der Rache gekommen.\n\nIhr könnt Vosh'gajin in der Blackrockspitze finden. Erschlagt sie und kehrt mit ihrem Schlangenstein zu mir zurück. Erledigt das und ich werde Euch den Weg eines Axtschmieds weisen.", objectives = "Begebt Euch zur Blackrockspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5307] = { title = "Verderbnis", description = "Wenn ich mit Euch kurz angebunden bin, dann gibt es einen Grund dafür. Die Pläne für die Erschaffung der großen Klinge, der Verderbnis, wurden von der schwarzen Wache gestohlen: den Skeletteliteeinheiten von Baron Rivendare.\n\nJa, Baron Rivendare von Stratholme.\n\nDer Schwertschmied der schwarzen Wache bewacht diese Pläne nun mit seinem ... Untod.\n\nErschlagt ihn, kehrt mit einem Beweis für diese Tat zurück und ich werde Euch den Weg eines Schwertschmieds weisen.", objectives = "Findet den Schwertschmied der schwarzen Wache in Stratholme und vernichtet ihn. Holt die Insignien der schwarzen Wache und kehrt zu Seril Scourgebane zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5321] = { title = "Der Schläfer ist erwacht", description = "Ich war auf dem Weg zu Maestras Posten, um mich mit Liladris Moonriver zu treffen, als ich beschloss, hier anzuhalten und ein kurzes Nickerchen zu machen. Seit ich aus dem Smaragdgrünen Traum aufgewacht bin, bin ich ständig so müde...\n\n<gähnt>\n\nKönntet Ihr mir den Weg zeigen? Ich weiß, dass Maestras Posten südlich von hier ist, entlang der Straße in Ashenvale. Es kann gefährlich werden, daher hoffe ich, dass Ihr einige Freunde habt, die sich uns anschließen werden.\n\nAußerdem könnte ich einschlafen. Wenn Ihr mich also einmal aufwecken müsst, dann benutzt dazu bitte mein Horn. Ihr findet es in der Truhe hier.", objectives = "Begleitet Kerlonian Evershade zu Liladris Moonriver in Maestras Posten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5341] = { title = "Das Familienvermögen der Barovs", description = "In der Scholomance liegt das Familienvermögen der Barovs. Ich, Alexi Barov, bin einer der beiden letzten verbliebenen Erben des Hauses Barov. Mein Bruder Weldon ist der andere.\n\nWeldon, der jämmerliche Feigling, floh während des Krieges und hielt so an seiner wertlosen Existenz als Mensch fest.\n\nJetzt sucht er nach den Besitzurkunden, damit er das Vermögen für sich beanspruchen kann. Holt die Besitzurkunden, bevor mein Bruder es tut, und ich werde Euch reicher machen, als Ihr je zu träumen gewagt habt.", objectives = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5342] = { title = "Der letzte Barov", description = "Da mein Bruder noch am Leben ist, wird es möglicherweise einen Disput darüber geben, wer der Hauptbegünstigte des Familienvermögens ist. Das darf nicht sein.\n\nEin niederer Gossenstreuner wie Ihr hat ja wohl nichts gegen einen kleinen kaltblütigen Mord einzuwenden, hoffe ich.\n\nEs ist eine einfache Aufgabe und ich erwarte, dass Ihr sie erfüllt... das heißt, falls Ihr Eure Belohnung erhalten wollt.\n\nWeldon sitzt unter dem Schutz der Allianz im Chillwind-Lager im Osten. Erschlagt ihn, bringt seinen Kopf zurück.\n\n<Alexi gähnt.>\n\nUnd jetzt fort mit Euch.", objectives = "Begebt Euch zum Chillwind-Lager - Territorium der Allianz - und ermordet Weldon Barov. Nehmt seinen Kopf und kehrt zu Alexi Barov zurück.\n\nSeid gewarnt, Weldon wird wahrscheinlich gut von Abschaum der Allianz geschützt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5343] = { title = "Das Familienvermögen der Barovs", description = "Mein lieber Bruder Alexi. Was für ein Narr war ich doch, sein Leben zu verschonen. Ich sah dem Feind ins Gesicht, einem der Untoten, und ließ ihn am Leben.\n\n<Weldon spuckt aus.>\n\nUnd jetzt sucht er nach MEINEM Erbe. Das darf einfach nicht sein.\n\nSucht die Besitzurkunden meiner Familie, bevor sie diesem niederträchtigen Bastard in seine knochigen Hände fallen, und ich werde Euch mit großem Reichtum belohnen. Sie liegen irgendwo in den Ruinen der Scholomance. Beeilt Euch!", objectives = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5344] = { title = "Der letzte Barov", description = "Da die Besitzurkunden beschafft sind, bleibt nur noch eine Sache zu tun. Alexi muss getötet werden. Wenn er tot ist, brauche ich nicht mehr zu fürchten, dass eine skrupellose Bande von Söldnern meinen Kopf haben will.\n\nDie Aufgabe ist einfach. Alexi versteckt sich unter dem Schutz der Horde - beim Bollwerk.\n\nNein, ich erwarte nicht, dass Ihr einfach nur hingeht und ihn tötet, ich will seinen Kopf! Wie Ihr ihn bekommt ... tja, dieser Part ist Euch überlassen. Ein derartiges Verhalten ist einem von meiner edlen Erziehung nicht würdig..", objectives = "Begebt Euch zum Bollwerk - Territorium der Horde - und ermordet Alexi Barov. Nehmt seinen Kopf und kehrt zu Weldon Barov zurück.\n\nSeid gewarnt, Alexi wird wahrscheinlich gut durch Abschaum der Horde geschützt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5361] = { title = "Stammbaum", description = "Mein Bruder Nataka ist beim Geistwandlerposten drüben in Desolace stationiert. Also, worum ich Euch bitten möchte, ist... könntet Ihr ihm diesen Bericht von mir geben? Ein Jahr ist vergangen, seit ich ihm das letzte Mal schrieb, und es gab seitdem ungewöhnliche Zentaurenaktivitäten, über die er informiert werden sollte.\n\nReist zum Steinkrallengebirge nördlich von Crossroads und dann westlich zum verbrannten Tal. Begebt Euch von dort aus südlich nach Desolace; dort findet Ihr eine Straße, die gen Süden zum Geistwandlerposten führt.", objectives = "Bringt den Bericht von Klippenbehüter Longhorn zu Nataka Longhorn am Geistwandlerposten in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5381] = { title = "Hand von Iruxos", description = "Die Burning Blade besitzen den Dämonenkasten. Darin liegt die mächtige Hand von Iruxos. Die Burning Nlade verwenden sie, um dämonische Portale in Mannorocs Koven zu öffnen. Wir müssen die Flut der Dämonen stoppen, die in unsere Welt eindringt, $n!\n\nWendet diese Dämonenhacke auf den roten Kristall in der Festung Thunder Axe an, um Zugang zu dem Dämonenkasten zu erlangen.", objectives = "Holt den Dämonenkasten aus der Festung Thunder Axe und kehrt damit zu Taiga Wisemane nach Shadowprey zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5382] = { title = "Doktor Theolen Krastinov, der Schlächter", description = "Krastinov ist für den Tod von Tausenden verantwortlich. Er muss bestraft werden, die Gerechtigkeit muss ihren Lauf nehmen.\n\nSucht ihn und bringt jene Qual über ihn, die er über zahllose Unschuldige gebracht hat. Wenn er vernichtet ist, verbrennt unsere Überreste. Verwandelt sie in Asche, $n.", objectives = "Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5384] = { title = "Kirtonos der Herold", description = "Das ist es, $n.\n\n<Eva zeigt auf die Phiole in der Tasche.>\n\nDas Blut von Unschuldigen. Das reinste Blut... damit wird Krastinovs Meister besänftigt.\n\nMit diesem Blut kann Kirtonos beschworen werden. Mit diesem Blut muss Kirtonos auch vernichtet werden.\n\nBringt dieses Blut auf die Veranda. Legt es auf die Kohlenpfanne. Kirtonos wird kommen - er kann nicht widerstehen. Wenn er erscheint, entfesselt die Wut und den Zorn von Tausenden unschuldigen Toten über ihm.\n\nWenn Ihr erfolgreich seid, werdet Ihr mehr verdienen als nur unsere Dankbarkeit.", objectives = "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.\n\nKämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5385] = { title = "Die Überreste von Trey Lightforge", description = "Ihr hebt den Sack vorsichtig auf und macht Euch auf den Rückweg zu Jessir Moonbow an der Grenze des Teufelswaldes und Ashenvale. Hoffentlich wird dem Paladin der ihm zustehende Respekt erwiesen, wenn Ihr seine Überreste seinen Freunden übergeben habt.", objectives = "Bringt die Überreste von Trey Lightforge zu Jessir Moonbow im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5386] = { title = "Der Fang des Tages", description = "Der Geruch von gekochtem Fisch ist hier im Geistwandlerposten schon längst verschwunden. Die Trolle von Shadowprey sind die Besten, wenn es um das Fangen von Fischen geht... aber leider habe ich aufgrund all der Zentaurenaktivitäten nicht genug Zeit, um eine Reise zu den Trollen zu unternehmen. Hm...\n\nTut mir einen Gefallen und reist nach Shadowprey. Sprecht mit dem dortigen Angler Jinar'Zillen und bringt mir mein Leibgericht, Blutbauchfisch. Die Straße südlich von hier bringt Euch nach Westen zu dem Trolldorf.", objectives = "Sprecht mit Jinar'Zillen in Shadowprey und bringt Nataka Longhorn dann 2 Blutbauchfische.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
