quests[5441] = { title = "Faule Peons", description = "Verfluchte Peons! Sie arbeiten ja hart daran, Holz aus den Bäumen im Tal zu gewinnen, aber sie machen ständig Nickerchen! Ich brauche jemanden, der dabei hilft, die Peons auf Zack zu halten.\n\nIhr seht wie geschaffen für meinen Auftrag aus, $R. Hier, Ihr nehmt jetzt diesen Totschläger und lasst ihn auf allen faulen Peons tanzen, die Ihr bei der Arbeit schlafend vorfindet. Ein ordentlicher Schlag wird sie schnell wieder an die Arbeit bringen! Bringt mir den Totschläger wieder, wenn Ihr fertig seid.\n\nVerdammte faule Peons ...", objectives = "Benutzt den Totschläger des Großknechts an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Totschläger des Großknechts zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5461] = { title = "Der Mensch Ras Frostraunen", description = "Die Untoten fürchten das Leben genauso sehr wie die Lebenden den Tod fürchten. Es ist nicht ungewöhnlich, dass ein denkender Untoter alle Überreste seines vorherigen Lebens vollständig zerstört, nachdem er zum Untoten wurde.\n\nLeider benötigen wir, um ein Artefakt zu erschaffen, das Ras Frostraunen wieder in einen Sterblichen zurückverwandeln kann, ein Andenken aus seinen Jahren unter den Lebenden.\n\nIhr müsst Euch zur zerstörten Stadt von Stromgarde begeben, Frostraunens Heim, und nach solch einem Gegenstand suchen. Möge das Glück mit Euch sein, $n.", objectives = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduke zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5462] = { title = "Der Sterbende Ras Frostraunen", description = "Das Andenken muss auf besudeltem Boden korrekt eingestellt werden.\n\nMan erzählt sich, dass Stratholme der Ort sei, an dem Frostraunen dem Lichkönig erlag. Auf diesem blutigen Boden gab er sein Leben - frei und mit einem Motiv -, um einer der Unsterbenden zu werden.\n\nDieser Ort muss gefunden werden.\n\nEs gibt einen untoten Dissidenten der Geißel, der durch die Bansheekönigin befreit wurde, aber der Sache der Argentumdämmerung gegenüber loyal ist. Sucht ihn: Leonid Barthalomew der Geachtete. Er könnte mehr wissen. Sucht die Hoffnung des Lichts auf, $N.", objectives = "Reist zur Hoffnung des Lichts in den Östlichen Pestländern und sucht Leonid Barthalomew den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5463] = { title = "Menethils Geschenk", description = "Ich sah zu, wie der Mensch Ras Frostraunen seine unsterbliche Seele dem Lichkönig verpfändete. Er setzte den Dolch an seiner eigenen Kehle an und durchschnitt sie mit einem Lächeln von einem Ohr zum anderen. Sein Körper brach in den Grenzen des Pentagramms zusammen. Der Lichkönig stand über dem gefallenen Magier, und mit einer einzigen Bewegung wurde Ras Frostraunen der Lich geboren.\n\n<Leonid blickt zu Boden und sieht Euch dann an.>\n\nJa, $R, ich erinnere mich. Was Ihr sucht, hat einen Namen - Menethils Geschenk: Der vom Lichkönig gesegnete Boden - heiliger Boden für die Geißel.", objectives = "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5464] = { title = "Menethils Geschenk", description = "Die Seele des Gefallenen hängt sich an das, was sein ehemaliges Leben repräsentiert, und verwandelt den Gegenstand in ein seelengebundenes Andenken. Ihr hebt den Gegenstand auf und verstaut ihn in Eurem Rucksack.", objectives = "Bringt das seelengebundene Andenken zu Leonid Barthalomew in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5465] = { title = "Seelengebundenes Andenken", description = "Kehrt mit dem Andenken zu Marduke zurück, $N. Er wird Euch über die Anwendung instruieren.", objectives = "Kehrt zu Magistrat Marduke in Caer Darrow zurück. Zeigt ihm das seelengebundene Andenken.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5466] = { title = "Der Lich Ras Frostraunen", description = "Es verbleibt noch eine Aufgabe, $n. Tretet dem Lich Ras Frostraunen in seinem Unterschlupf gegenüber.\n\nBenutzt die Macht des Andenkens gegen die Bestie - seid unerbittlich in Euren Taten! Haltet den Schlägen stand, mit denen das um sich schlagende Biest Euch sicherlich eindecken wird. Gebt dem Schmerz nicht nach!\n\nWenn das Ritual abgeschlossen ist, wird Ras wieder ein Sterblicher sein. An diesem Punkt muss er getötet werden. Schlagt ihn nieder und nehmt Euch seinen menschlichen Kopf.", objectives = "Sucht Ras Frostraunen in der Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5481] = { title = "Gordos Aufgabe", description = "Meister will Kräuter. Wir große Hände haben und nicht gut greifen können. Ihr uns helfen und wir Euch nicht wehtun. Wir Düsterkraut brauchen. Viele Kräuter hier und bei Straße.\n\nWenn Ihr Düsterkraut haben, Ihr bringen zu Meister Holland auf Brill-Friedhof.", objectives = "Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland auf den Brill-Friedhof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5482] = { title = "Verdammniskraut", description = "Ihr seht also die Zwickmühle, in der ich mich befinde, $n. Dieses Ding da draußen sammelt die falschen Kräuter! Ich werde Euch dafür belohnen, wenn Ihr sammelt, was ich wirklich benötige. Bringt mir genug Verdammniskraut und ich werde Euch eine angemessene Belohnung geben.\n\nSoweit mir bekannt ist, verseucht es gern die Flora in der Nähe des Massengrabs, nördlich des Friedhofes von Brill. Beeilt Euch und hütet Euch vor den Gnollen in dem Gebiet.", objectives = "Sammelt 10 Verdammniskräuter und bringt sie zu Jungapotheker Holland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5501] = { title = "Knochensammler", description = "Wir sitzen hier auf einer Goldmine, ich sage Euch - einer Goldmine! Kodoknochen werden die Welt für immer verändern... Ich habe Kunden, die daraus Möbel, Musikinstrumente und sogar Sprengpulver herstellen.\n\nEine Karawane kommt hier vorbei, die meine Kodoknochen mitnimmt und sie dann in Shadowprey verkauft. Wenn Ihr zum Kodofriedhof südlich von hier gehen und mir zehn Kodoknochen bringen könntet, würde ich Euch dafür etwas anderes geben. Ist das ein Geschäft?", objectives = "Bringt Bibbly F'utzbuckle bei Kormeks Hütte 10 Kodoknochen vom Kodofriedhof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5502] = { title = "Tageseltern der Horde", description = "Ihr wart die ganze Zeit so gut zu mir, $n. Nie hätte ich erwartet, während der Kinderwoche so viel Spaß zu haben! Danke schön.\n\nIch wünschte, all die anderen Waisenkinder hätten das Glück, die ganzen Sachen zu sehen, die wir gesehen haben. Meint Ihr, wir finden Blax Flaschenzünder wieder und bekommen einen Schaumstoffschwertständer von ihm? Ich glaube, er schiebt noch immer seinen Karren durch die Hauptstraße in der Gasse. Dann könnten alle im Waisenhaus auch ihren Spaß haben!\n\nDanach wird es aber Zeit, nach Hause zurückzukehren.", objectives = "Kauft einen Schaumstoffschwertständer bei Blax Flaschenzünder in Orgrimmars Gasse. Bringt anschließend Euren Schützling in das Waisenhaus von Orgrimmar zurück, indem Ihr die Pfeife des Orcwaisenkindes an Waisenmatrone Schlachterbe in der Gasse übergebt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5503] = { title = "Anstecknadel der Argentumdämmerung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5504] = { title = "Mäntel der Dämmerung", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, $N. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\n Wenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", objectives = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5505] = { title = "Der Schlüssel zur Scholomance", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
