quests[5513] = { title = "Mäntel der Dämmerung", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, $N. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\n Wenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", objectives = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Breechlock an der Kapelle des hoffnungsvollen Lichts, östliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5514] = { title = "Sold reimt sich auf...", description = "Der Goblin, mit dem Ihr sprechen müsst, ist Krinkle Goodsteel. Er geht mit seinen Fertigkeiten bei den höchsten Bietern in Gadgetzan, in der Tanariswüste, hausieren. Er dürfte der Einzige sein, der die Form herstellen kann, die wir benötigen, und seine Dienste werden nicht billig sein. Wir bitten Euch, tief in die Tasche zu greifen, indem Ihr die Gebühr zahlt, die er fordert.\n\nIch bin Apotheker, kein Bankier. Wenn ich Gold herumliegen hätte, wäre ich sicher nicht hier.\n\nIch schätze, ich hab meine Gedanken mal wieder laut ausgesprochen. Upps.\n\nGadgetzan erwartet Euch! Viel Glück!", objectives = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5515] = { title = "Krastinovs Tasche der Schrecken", description = "Ein großes Gewicht wurde von unseren Herzen genommen, $n, aber Eure Aufgabe ist noch nicht vollendet. Krastinovs Meister, Kirtonos, lebt immer noch.\n\nBevor Ihr aber Kirtonos gegenübertretet, müsst Ihr Euch zuerst eine Methode besorgen, mit der Ihr ihn beschwören könnt.\n\nEs heißt, dass Jandice Barov das Blut Unschuldiger von Krastinov zu Kirtonos bringt.\n\nSucht sie in den versunkenen Katakomben der Scholomance und streckt sie nieder. Bringt alle Hinweise zurück, die Ihr findet.", objectives = "Sucht nach Jandice Barov in der Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5517] = { title = "Der Chromatische Mantel der Dämmerung", description = "$G Bruder : Schwester; $n -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", objectives = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Knackschloss an der Kapelle des Hoffnungsvollen Lichts, Östliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5518] = { title = "Der Ogeranzug der Gordok", description = "Wenn Ihr versuchen wollt gegen den König dieser Bruchbude zu kämpfen - und ich denke, dass Ihr genau das vorhabt - dann müsst Ihr erstmal an Hauptmann Krombruch vorbei. Sicher könnt Ihr ihn einfach töten. Doch vielleicht wollt Ihr diesen Oger ja am Leben lassen.\n\nEs stellt sich nur die Frage, wie? Nun, ich bin hier schon eine ganze Weile und ich denke, dass ich Euch einen Ogeranzug anfertigen kann, der ausreicht, um diese Kerle zu täuschen. Das einzige Problem wird seine Stabilität sein - zehn Minuten sind das Maximum. Besorgt mir alles was ich brauche und Ihr bekommt einen Ogeranzug. Ich warte hier solange...", objectives = "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Zwingschraub. Momentan ist er im Gordokflügel von Düsterbruch angekettet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5519] = { title = "Der Ogeranzug der Gordok", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5521] = { title = "Der Chromatische Mantel der Dämmerung", description = "$G Bruder : Schwester; $n -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", objectives = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Funkellicht im Zugwindlager in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5522] = { title = "Leonidas Bartholomäus", description = "Ich habe eine Botschaft von meinem Meister Vectus erhalten. Na ja, die Botschaft war nicht wirklich von Vectus... sie war von jemandem namens Leonid Barthalomew. Ich kenne Leonid nicht, aber er kannte meinen Meister, und niemand kennt meinen Meister, außer er lässt es zu.\n\nLeonid sagt, dass Vectus die Dracheneier will. Er möchte, dass Ihr sie ihm zur Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern bringt.\n\nDas tut weh! Warum Ihr? Vertraut Vectus mir nicht? Ach, egal... nehmt einfach die Eier und berichtet Leonid, dass ich getan habe, was unser Meister befahl.", objectives = "Bringt die gefrorenen Eier zu Leonid Barthalomew in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5524] = { title = "Der Chromatische Mantel der Dämmerung", description = "$G Bruder : Schwester; $n -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", objectives = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5525] = { title = "Befreit Knot!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5526] = { title = "Die Splitter der Teufelsranke", description = "Euer Wissen über Eldre'Thalas - Düsterbruch - in Feralas wird nun gebraucht, $N. Im Ostteil der zerstörten Stadt erstreckt sich das Herrschaftsgebiet von Alzzin dem Wildformer. Begebt Euch mit der gebotenen Eile und Tapferkeit dorthin.\n\nDie korrumpierte Frucht des Gedeihens - die Teufelsranke - sollte sich in Alzzins Nähe befinden. Wenn er fällt, versucht soviel wie möglich von der Essenz der Teufelsranke zu erlangen. Versiegelt diese in dem Reliquiar und bringt es zu mir.\n\nViel Glück und Cenarius' Kraft sei mit Euch!", objectives = "Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5527] = { title = "Ein Reliquiar der Reinheit", description = "Zuerst müssen wir einen Behälter finden, in dem eine sehr stark verderbte Substanz transportiert werden kann, ohne das der Träger Nebenwirkungen davonträgt. Meines Wissens nach, gibt es nur einen Gegenstand der geeignet ist, darin etwas so abscheuliches wie eine Teufelsranke aufzubewahren: ein Reliquiar der Reinheit.\n\nTief in der Einöde von Silithus befinden sich die Überreste des Nachtelfenpostens Südwind. Vor vielen, vielen Jahren gab es dort ein Reliquiar. Wenn wir Erfolg haben wollen, müsst Ihr die Ruinen durchsuchen, in der Hoffnung dort ein Reliquiar der Reinheit zu finden.", objectives = "Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5528] = { title = "Der Gordokgeschmackstest", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5529] = { title = "Verseuchte Jungtiere", description = "Die Argentumdämmerung hat kürzlich erfahren, dass die Geißel ihren eigenen verseuchten Drachenschwarm erschafft! Wir müssen sie stoppen - wenn die Geißel eine Großdrachenstreitmacht auf die Beine stellt, wird sie unbehelligt ganz Azeroth verwüsten!\n\nIhre Totenbeschwörer züchten verseuchte Großdrachen in der Scholomance, in der Mitte des Darrowmeresees.\n\nBegebt Euch zur Scholomance und tötet so viele Jungtiere wie nur möglich ... bevor sie größer werden können!", objectives = "Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5531] = { title = "Betina Moppelzink", description = "Die Eier, die Ihr gebracht habt, sollten in Experimenten der Geißel verwendet werden, um einen verseuchten Drachenschwarm zu erschaffen. Diese gefrorenen schwarzen Dracheneier wären für ihre Studien unersetzlich gewesen und hätten ihren Zeitplan sicherlich beschleunigt.\n\nNun ist es an der Zeit, dass wir ihre Forschung beenden.\n\nBringt die gefrorenen Eier zu Betina Bigglezink da draußen. Sie ist in Wissenschaft und Alchimie sehr bewandert und hat eine Waffe hergestellt, die wir gegen die Geißel einsetzen können. Mit Eurer Hilfe werden wir ihnen einen schweren Schlag versetzen.", objectives = "Bringt die gefrorenen Eier zu Betina Bigglezink.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5533] = { title = "Scholomance", description = "Auf der Insel Caer Darrow liegt die Scholomance - ein elendes Zentrum der Totenbeschwörung und des Bösen der Geißel. Unser Feind lebt im Inneren und führt unaussprechliche Taten der Verderbtheit an nichts ahnenden Opfern aus... zumindest vermuten wir das. Eine Tür versperrt den Weg, und ganz gleich was wir versuchen, der Zutritt ist nur mit dem richtigen Schlüssel möglich.\n\nAlchimist Arbington weiß viel über die Scholomance und hat eine Idee, wie ein Schlüssel zu erlangen ist. Ihr habt mir Euren Wert bewiesen und nun vertraue ich Euch diese Aufgabe an. Sprecht mit ihm über diese Angelegenheit.", objectives = "Sprecht mit Alchimist Arbington an der Chillwindspitze, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5534] = { title = "Kim'jaels 'fehlende' Ausrüstung", description = "Was?! Was?!\n\nDas war nicht gut genug für Euch? Wisst Ihr, wie teuer diese Sprengstoffe sind? Die kosten... ach, egal. Ihr wollt also echtes Geld machen, ja? Na denn... so läuft das im Geschäftsleben: Ihr beweist, dass Ihr ein wertvoller Angestellter seid, und dann werdet Ihr entsprechend belohnt, nachdem Ihr schön brav durchgehalten habt.\n\nFalls Ihr also ein 'wertvoller' Angestellter seid, dann begebt Euch zu den Ruinen von Eldarath und bringt mir irgendeine Rune, nach der diese Blutelfen gesucht haben. Anscheinend befindet sie sich im Besitz der Naga.", objectives = "Sucht, in den Ruinen von Eldarath irgendeine Rune, die die Naga in ihrem Besitz haben, und bringt sie Kim'jal in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5535] = { title = "Spirituelle Unruhe", description = "Vor langer Zeit gehörten die Hochgeborenen zu den mächtigsten Schülern des Arkanen, die die Nachtelfen je hervorgebracht hatten. Die Verderbnis, die mit solchen Studien einhergeht, brachte großes Unglück über die Gesellschaft der Nachtelfen und wirkte sich in großem Umfang auf Azeroth aus ... wie Ihr sicherlich wisst.\n\nIch habe den Schildwachen versprochen, dass ich die Geister aus ihren sterblichen Banden befreie, wenn ich sie finde. Wenn Ihr dasselbe tun würdet, kann ich Euch sicherlich belohnen.\n\nDie Geister spuken im Shadowsong-Schrein, von hier aus im Nordosten.", objectives = "Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5536] = { title = "Ein Land voller Hass", description = "Der Satyr, ein entstellter, böser Aspekt der Nachtelfen, infiziert jetzt die hochheiligen Länder, die einst von Cenarius bereist wurden. Ich kann nicht für die Nachtelfen sprechen, wenn es um die ganzen Gräueltaten geht, die diese dämonischen Kreaturen begangen haben, aber ich habe der Erdenmutter einen Eid geschworen, den Elfen zu helfen, das Land von solch einer Plage zu befreien.\n\nIch bin sicher, dass Ihr Euch beweisen würdet, wenn Ihr mir bei der Reinigung helfen würdet.\n\nNordöstlich von hier könnt Ihr den Haldarrklan finden. Kehrt zu mir zurück, nachdem Ihr Euch gegen ihre Stärke bewiesen habt.", objectives = "Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zu Ashenvale zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5537] = { title = "Skelettfragmente", description = "Der Schlüssel zur Scholomance wird 'Skelettschlüssel' genannt. Er muss aus den Überresten eines Skeletts geschmiedet werden- eigentlich aus mehreren - und er darf nur durch die stärksten Metalle in einer geeigneten Form gehärtet werden. Ein Signet der Macht von einem Wesen, das das Portal zur Scholomance natürlich öffnen kann, gibt dem Schlüssel seine endgültige Funktion.\n\nAber eines nach dem anderen, $N. Wir benötigen Skelettfragmente für das Schmieden des Schlüssels. Skelette innerhalb von Andorhal sollten den gewünschten Effekt bringen, aber die außerhalb der Mauern könnten vielleicht auch ausreichen.", objectives = "Bringt 15 Skelettfragmente zu Alchimist Arbington an der Chillwindspitze, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5538] = { title = "Sold reimt sich auf...", description = "Der Goblin, mit dem Ihr sprechen müsst, ist Krinkle Goodsteel. Er geht mit seinen Fertigkeiten bei den höchsten Bietern in Gadgetzan, in der Tanariswüste, hausieren. Er dürfte der Einzige sein, der die Form herstellen kann, die wir benötigen, und seine Dienste werden nicht billig sein. Wir bitten Euch, tief in die Tasche zu greifen, indem Ihr die Gebühr zahlt, die er fordert.\n\nIch bin Alchimist, kein Bankier. Wenn ich Gold herumliegen hätte, wäre ich sicher nicht hier.\n\nIch schätze, ich hab meine Gedanken mal wieder laut ausgesprochen. Upps.\n\nGadgetzan erwartet Euch! Viel Glück!", objectives = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5541] = { title = "Munition für Rumbleshot", description = "Hegnar Rumbleshot verkauft Gewehre an der Straße nach Anvilmar. Scharfschützen und Mörsertrupps verbringen viel Zeit damit, in der Nähe seines Geschäfts zu üben, und er braucht ständig neue Munition.\n\nAber... die letzte Munitionskiste, die ich ihm geschickt habe, ist unterwegs verloren gegangen. Mein Kurier sagte, er lagerte nahe des altgedienten Baus, als Wendigos ihn davonjagten... und der Dummkopf hat Rumbleshots Munition zurückgelassen!\n\n$N, könnt Ihr diese Munition beschaffen und zu Rumbleshot bringen? Er wartet darauf und ihm gehen bestimmt bald die Vorräte aus.", objectives = "Bringt Rumbleshots Munition zu Hegnar Rumbleshot in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5542] = { title = "Dämonenhunde", description = "Wenn Ihr hier bleiben wollt, bitte ich Euch nur, Euren Unterhalt zu verdienen. Wir haben hier viele Plagegeister, denen etwas 'Disziplin' gut tun würde.\n\nIhr könnt mit den Seuchenhunden und den kleinen Seuchenhunden beginnen.\n\nViel kann ich Euch im Gegenzug nicht anbieten, aber ein warmes Mahl und ein wenig Konversation wäre Euch garantiert, wenn Ihr erfolgreich seid.", objectives = "Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
